<style>

/* =========================================================
 GLOBAL
========================================================= */

#cbx-navbar-wrap,
#cbx-navbar-wrap *,
#cbx-navbar-wrap *::before,
#cbx-navbar-wrap *::after{
 box-sizing:border-box;
}

#cbx-navbar-wrap{
 --cbx-red:#B5121B;
 --cbx-deep-red:#8E0E16;
 --cbx-gold:#C9A227;
 --cbx-light-gold:#E5C766;
 --cbx-white:#FFFFFF;
 --cbx-ivory:#FCFAF6;
 --cbx-text:#171717;
 --cbx-muted:#6B6B6B;
 --cbx-border:#E8E4DC;

 width:100vw !important;
 max-width:100vw !important;
 margin-left:calc(50% - 50vw) !important;
 margin-right:calc(50% - 50vw) !important;

 position:relative;
 z-index:99999;

 font-family:Inter,Manrope,Arial,sans-serif;
}

#cbx-navbar-wrap a{
 text-decoration:none !important;
}


/* =========================================================
 HEADER
========================================================= */

#cbx-header{
 width:100%;
 position:relative;
 z-index:99999;
 background:#fff;
}


/* =========================================================
 MAIN HEADER
========================================================= */

.cbx-main-header{
 width:100%;
 min-height:146px;
 padding:0 4.5vw;

 display:flex;
 align-items:center;
 gap:30px;

 background:#fff;
 border-bottom:1px solid #eee8df;
}


/* =========================================================
 LOGO
========================================================= */

.cbx-logo-link{
 width:178px;
 height:138px;

 flex:0 0 178px;

 display:flex;
 align-items:center;
 justify-content:center;
}

.cbx-logo{
 width:178px !important;
 height:138px !important;

 max-width:none !important;
 object-fit:contain !important;

 display:block;
}


/* =========================================================
 MAIN NAV
========================================================= */

.cbx-main-nav{
 display:flex;
 align-items:center;
 gap:26px;

 flex:0 0 auto;
}

.cbx-main-nav a{
 position:relative;

 color:#191919 !important;

 font-size:15px;
 font-weight:600;
 line-height:1;

 white-space:nowrap;

 padding:10px 0;

 transition:.25s ease;
}

.cbx-main-nav a::after{
 content:"";

 position:absolute;

 left:0;
 bottom:2px;

 width:0;
 height:2px;

 background:var(--cbx-red);

 transition:.25s ease;
}

.cbx-main-nav a:hover{
 color:var(--cbx-red) !important;
}

.cbx-main-nav a:hover::after{
 width:100%;
}


/* =========================================================
 SEARCH
========================================================= */

.cbx-search-area{
 position:relative;

 margin-left:auto;

 width:315px;
 max-width:315px;
}

.cbx-search-form{
 width:100%;
 height:47px;

 display:flex;
 align-items:center;

 background:#fff;

 border:1px solid #dcd6cc;
 border-radius:4px;

 overflow:hidden;

 transition:.25s ease;
}

.cbx-search-form:focus-within{
 border-color:var(--cbx-gold);
 box-shadow:0 0 0 3px rgba(201,162,39,.10);
}

.cbx-search-icon{
 width:45px;
 height:100%;

 display:flex;
 align-items:center;
 justify-content:center;

 flex:0 0 45px;
}

.cbx-search-icon svg{
 width:19px;
 height:19px;

 fill:none;
 stroke:#777;
 stroke-width:1.8;
}

#cbx-search-input{
 width:100% !important;
 min-width:0 !important;
 height:100% !important;

 border:0 !important;
 outline:0 !important;

 padding:0 8px !important;

 background:transparent !important;

 color:#222 !important;

 font-size:14px !important;
 font-family:Inter,Manrope,Arial,sans-serif !important;
}

#cbx-search-input::placeholder{
 color:#999;
}

.cbx-search-submit{
 height:100%;

 border:0;
 border-left:1px solid #eee8df;

 padding:0 15px;

 background:#fff;

 color:var(--cbx-red);

 font-size:12px;
 font-weight:700;

 cursor:pointer;

 transition:.2s ease;
}

.cbx-search-submit:hover{
 background:var(--cbx-red);
 color:#fff;
}


/* =========================================================
 LIVE SEARCH DROPDOWN
========================================================= */

.cbx-search-results{
 position:absolute;

 top:calc(100% + 10px);
 left:0;

 width:100%;

 background:#fff;

 border:1px solid #e5dfd5;

 border-radius:10px;

 box-shadow:0 20px 50px rgba(0,0,0,.14);

 overflow:hidden;

 display:none;

 z-index:100000;

 animation:cbxSearchOpen .18s ease;
}

.cbx-search-results.cbx-visible{
 display:block;
}

@keyframes cbxSearchOpen{
 from{
 opacity:0;
 transform:translateY(-5px);
 }

 to{
 opacity:1;
 transform:translateY(0);
 }
}

.cbx-results-heading{
 height:42px;

 display:flex;
 align-items:center;
 justify-content:space-between;

 padding:0 15px;

 background:#faf8f4;

 border-bottom:1px solid #eee8df;

 color:#8b8278;

 font-size:10px;
 font-weight:800;

 letter-spacing:1.2px;
}

#cbx-result-count{
 color:var(--cbx-red);
}

#cbx-results-list{
 max-height:390px;
 overflow-y:auto;
}

.cbx-result-item{
 width:100%;

 min-height:68px;

 display:flex;
 align-items:center;
 gap:12px;

 padding:9px 13px;

 background:#fff;

 border-bottom:1px solid #f1eee9;

 cursor:pointer;

 transition:.18s ease;
}

.cbx-result-item:hover{
 background:#fcfaf6;
}

.cbx-result-image{
 width:48px;
 height:48px;

 flex:0 0 48px;

 border-radius:7px;

 overflow:hidden;

 background:linear-gradient(135deg,#f7f2e8,#fff);

 border:1px solid #e9e2d8;

 display:flex;
 align-items:center;
 justify-content:center;

 color:var(--cbx-red);

 font-family:"Playfair Display",Georgia,serif;

 font-size:19px;
 font-weight:700;
}

.cbx-result-image img{
 width:100% !important;
 height:100% !important;

 object-fit:cover !important;

 display:block;
}

.cbx-result-content{
 min-width:0;
 flex:1;
}

.cbx-result-name{
 color:#1b1b1b;

 font-size:14px;
 font-weight:700;

 line-height:1.25;

 white-space:nowrap;
 overflow:hidden;
 text-overflow:ellipsis;
}

.cbx-result-name mark{
 background:rgba(201,162,39,.22);
 color:#111;

 padding:1px 2px;
 border-radius:2px;
}

.cbx-result-meta{
 margin-top:4px;

 color:#8a847b;

 font-size:10px;
 font-weight:600;

 white-space:nowrap;
 overflow:hidden;
 text-overflow:ellipsis;
}

.cbx-result-arrow{
 color:#aaa;

 font-size:17px;

 flex:0 0 auto;

 transition:.2s ease;
}

.cbx-result-item:hover .cbx-result-arrow{
 color:var(--cbx-red);
 transform:translateX(3px);
}

.cbx-search-loading{
 padding:25px 15px;

 text-align:center;

 color:#777;

 font-size:12px;
}

.cbx-search-empty{
 padding:25px 15px;

 text-align:center;

 color:#777;

 font-size:12px;
}

.cbx-view-all{
 min-height:47px;

 display:flex;
 align-items:center;
 justify-content:center;
 gap:8px;

 background:#fff;

 color:var(--cbx-red) !important;

 border-top:1px solid #eee8df;

 font-size:12px;
 font-weight:800;

 transition:.2s ease;
}

.cbx-view-all:hover{
 background:var(--cbx-red);
 color:#fff !important;
}


/* =========================================================
 SOCIAL
========================================================= */

.cbx-social{
 display:flex;
 align-items:center;
 gap:10px;
}

.cbx-social a{
 width:31px;
 height:31px;

 display:flex;
 align-items:center;
 justify-content:center;

 color:#555 !important;

 border-radius:50%;

 transition:.2s ease;
}

.cbx-social a:hover{
 color:#fff !important;
 background:var(--cbx-red);
}

.cbx-social svg{
 width:16px;
 height:16px;

 fill:currentColor;
}

.cbx-social svg rect,
.cbx-social svg circle:first-of-type,
.cbx-social svg path:first-of-type{
 fill:none;
 stroke:currentColor;
 stroke-width:1.7;
}

.cbx-social .cbx-play{
 fill:currentColor;
 stroke:none;
}


/* =========================================================
 CATEGORY BAR
========================================================= */

.cbx-category-bar{
 width:100%;

 min-height:72px;

 display:flex;
 align-items:center;

 background:
 linear-gradient(
 90deg,
 #8d0c14 0%,
 #b5121b 50%,
 #8d0c14 100%
 );

 border-top:1px solid rgba(229,199,102,.75);
 border-bottom:3px solid var(--cbx-gold);

 position:relative;
 z-index:99998;
}

.cbx-category-inner{
 width:100%;

 padding:0 4.5vw;

 display:flex;
 align-items:center;
 justify-content:center;

 gap:0;
}

.cbx-category-item{
 position:static;
 height:72px;

 display:flex;
 align-items:center;
}

.cbx-category-link{
 height:72px;

 padding:0 25px;

 display:flex;
 align-items:center;
 justify-content:center;
 gap:9px;

 color:#fff !important;

 font-family:Inter,Manrope,Arial,sans-serif;

 font-size:15px;
 font-weight:700;

 letter-spacing:.1px;

 white-space:nowrap;

 transition:.2s ease;

 position:relative;
}

.cbx-category-link::after{
 content:"";

 position:absolute;

 left:25px;
 right:25px;
 bottom:0;

 height:3px;

 background:var(--cbx-light-gold);

 transform:scaleX(0);

 transform-origin:center;

 transition:.2s ease;
}

.cbx-category-item:hover .cbx-category-link{
 background:rgba(255,255,255,.08);
}

.cbx-category-item:hover .cbx-category-link::after{
 transform:scaleX(1);
}

.cbx-chevron{
 width:7px;
 height:7px;

 border-right:1.7px solid #fff;
 border-bottom:1.7px solid #fff;

 transform:rotate(45deg) translateY(-2px);

 transition:.2s ease;
}

.cbx-category-item:hover .cbx-chevron{
 transform:rotate(225deg) translate(-1px,-1px);
}


/* =========================================================
 DROPDOWN LAYER
========================================================= */

#cbx-dropdown-layer{
 position:fixed;

 left:0;
 top:0;

 width:100%;
 height:0;

 z-index:100001;

 pointer-events:none;
}

.cbx-dropdown{
 position:fixed;

 display:none;

 width:min(780px,calc(100vw - 32px));

 max-height:calc(100vh - 150px);

 overflow:auto;

 padding:22px;

 background:#fff;

 border:1px solid #e5dfd5;

 border-top:3px solid var(--cbx-gold);

 border-radius:0 0 12px 12px;

 box-shadow:0 22px 60px rgba(0,0,0,.18);

 pointer-events:auto;
}

.cbx-dropdown.cbx-open{
 display:block;

 animation:cbxDropdownOpen .18s ease;
}

@keyframes cbxDropdownOpen{
 from{
 opacity:0;
 transform:translateY(-5px);
 }

 to{
 opacity:1;
 transform:translateY(0);
 }
}

.cbx-dropdown-heading{
 display:flex;
 align-items:center;
 justify-content:space-between;

 margin-bottom:18px;

 padding-bottom:13px;

 border-bottom:1px solid #eee8df;
}

.cbx-dropdown-heading h3{
 margin:2px 0 0 !important;

 color:#171717;

 font-family:"Playfair Display",Georgia,serif;

 font-size:24px !important;
 font-weight:600;

 line-height:1.1;
}

.cbx-small-label{
 color:var(--cbx-gold);

 font-size:9px;
 font-weight:800;

 letter-spacing:1.7px;
}

.cbx-dropdown-heading > a{
 color:var(--cbx-red) !important;

 font-size:11px;
 font-weight:800;

 text-transform:uppercase;
 letter-spacing:.5px;
}

.cbx-dropdown-heading > a:hover{
 color:var(--cbx-deep-red) !important;
}


/* =========================================================
 DROPDOWN CARDS
========================================================= */

.cbx-dropdown-grid{
 display:grid;

 grid-template-columns:repeat(3,minmax(0,1fr));

 gap:13px;
}

.cbx-drop-card{
 min-height:155px;

 position:relative;

 display:flex;
 flex-direction:column;

 justify-content:flex-end;

 overflow:hidden;

 border-radius:8px;

 background:#eee;

 border:1px solid #e6dfd5;

 transition:.25s ease;
}

.cbx-drop-card img{
 position:absolute;

 inset:0;

 width:100% !important;
 height:100% !important;

 object-fit:cover !important;

 display:block;

 transition:.35s ease;
}

.cbx-drop-card::after{
 content:"";

 position:absolute;

 inset:0;

 background:
 linear-gradient(
 to top,
 rgba(0,0,0,.82) 0%,
 rgba(0,0,0,.30) 48%,
 rgba(0,0,0,.02) 100%
 );
}

.cbx-drop-card span{
 position:relative;

 z-index:2;

 padding:13px 12px;

 color:#fff;

 font-size:12px;
 font-weight:750;

 line-height:1.25;
}

.cbx-drop-card:hover{
 transform:translateY(-3px);

 box-shadow:0 10px 25px rgba(0,0,0,.14);
}

.cbx-drop-card:hover img{
 transform:scale(1.06);
}


/* =========================================================
 TEXT DROPDOWN
========================================================= */

.cbx-dropdown-list{
 display:grid;

 grid-template-columns:repeat(2,minmax(0,1fr));

 gap:0 20px;
}

.cbx-dropdown-list a{
 min-height:45px;

 display:flex;
 align-items:center;

 padding:0 5px;

 color:#333 !important;

 border-bottom:1px solid #eee8df;

 font-size:13px;
 font-weight:650;

 transition:.2s ease;
}

.cbx-dropdown-list a::after{
 content:"→";

 margin-left:auto;

 color:#aaa;

 transition:.2s ease;
}

.cbx-dropdown-list a:hover{
 color:var(--cbx-red) !important;
}

.cbx-dropdown-list a:hover::after{
 color:var(--cbx-red);
 transform:translateX(3px);
}


/* =========================================================
 MOBILE ACTIONS
========================================================= */

.cbx-mobile-actions{
 display:none;
}


/* =========================================================
 MOBILE DRAWER
========================================================= */

#cbx-mobile-overlay{
 position:fixed;

 inset:0;

 background:rgba(0,0,0,.48);

 opacity:0;
 visibility:hidden;

 transition:.25s ease;

 z-index:100002;
}

#cbx-mobile-overlay.cbx-active{
 opacity:1;
 visibility:visible;
}

#cbx-mobile-drawer{
 position:fixed;

 top:0;
 right:0;

 width:min(88vw,380px);
 height:100vh;

 background:#fff;

 z-index:100003;

 transform:translateX(105%);

 transition:.3s cubic-bezier(.4,0,.2,1);

 box-shadow:-15px 0 45px rgba(0,0,0,.16);

 overflow-y:auto;
}

#cbx-mobile-drawer.cbx-active{
 transform:translateX(0);
}

.cbx-mobile-drawer-head{
 min-height:88px;

 padding:5px 18px;

 display:flex;
 align-items:center;
 justify-content:space-between;

 border-bottom:1px solid #eee8df;
}

.cbx-mobile-drawer-head img{
 width:110px !important;
 height:78px !important;

 object-fit:contain !important;
}

#cbx-mobile-close{
 width:40px;
 height:40px;

 border:0;

 background:#f8f5ef;

 border-radius:50%;

 color:#333;

 font-size:27px;
 line-height:1;

 cursor:pointer;
}

.cbx-mobile-search{
 padding:17px;
}

.cbx-mobile-search form{
 height:46px;

 display:flex;

 border:1px solid #ddd5c9;
 border-radius:5px;

 overflow:hidden;
}

.cbx-mobile-search input{
 min-width:0;
 flex:1;

 border:0 !important;
 outline:0 !important;

 padding:0 13px !important;

 background:#fff !important;

 font-size:13px !important;
}

.cbx-mobile-search button{
 width:48px;

 border:0;

 background:var(--cbx-red);

 color:#fff;

 cursor:pointer;
}

.cbx-mobile-search button svg{
 width:18px;
 height:18px;

 fill:none;
 stroke:#fff;
 stroke-width:1.8;
}

.cbx-mobile-nav{
 padding:0 17px 35px;
}

.cbx-mobile-nav > a{
 min-height:48px;

 display:flex;
 align-items:center;

 padding:0 7px;

 color:#222 !important;

 border-bottom:1px solid #eee8df;

 font-size:14px;
 font-weight:650;
}

.cbx-mobile-nav > a:hover{
 color:var(--cbx-red) !important;
}

.cbx-mobile-divider{
 height:18px;
}


/* =========================================================
 TABLET
========================================================= */

@media (max-width:1200px){

 .cbx-main-header{
 padding:0 25px;
 gap:20px;
 }

 .cbx-logo-link,
 .cbx-logo{
 width:155px !important;
 flex-basis:155px;
 }

 .cbx-logo{
 height:125px !important;
 }

 .cbx-main-nav{
 gap:18px;
 }

 .cbx-main-nav a{
 font-size:13px;
 }

 .cbx-search-area{
 width:255px;
 max-width:255px;
 }

 .cbx-social{
 display:none;
 }

 .cbx-category-inner{
 padding:0 15px;
 }

 .cbx-category-link{
 padding:0 15px;
 font-size:13px;
 }

 .cbx-category-link::after{
 left:15px;
 right:15px;
 }

}


/* =========================================================
 MOBILE
========================================================= */

@media (max-width:900px){

 .cbx-main-header{
 min-height:88px;

 height:88px;

 padding:0 16px;

 justify-content:space-between;

 gap:0;
 }

 .cbx-logo-link{
 width:110px;
 height:82px;

 flex:0 0 110px;

 margin-left:auto;
 margin-right:auto;
 }

 .cbx-logo{
 width:110px !important;
 height:82px !important;
 }

 .cbx-main-nav,
 .cbx-search-area,
 .cbx-social,
 .cbx-category-bar{
 display:none;
 }

 .cbx-mobile-actions{
 position:absolute;

 right:16px;

 display:flex;
 align-items:center;

 gap:5px;
 }

 .cbx-mobile-actions button{
 width:40px;
 height:40px;

 border:0;

 background:transparent;

 display:flex;
 align-items:center;
 justify-content:center;

 cursor:pointer;
 }

 #cbx-mobile-search-btn{
 color:#222;
 }

 #cbx-mobile-search-btn svg{
 width:20px;
 height:20px;

 fill:none;
 stroke:currentColor;
 stroke-width:1.8;
 }

 #cbx-menu-btn{
 flex-direction:column;

 gap:5px;
 }

 #cbx-menu-btn span{
 width:22px;
 height:2px;

 background:#222;

 border-radius:3px;

 transition:.25s ease;
 }

 #cbx-menu-btn.cbx-open span:nth-child(1){
 transform:translateY(7px) rotate(45deg);
 }

 #cbx-menu-btn.cbx-open span:nth-child(2){
 opacity:0;
 }

 #cbx-menu-btn.cbx-open span:nth-child(3){
 transform:translateY(-7px) rotate(-45deg);
 }

 #cbx-search-results{
 position:fixed;

 top:88px;
 left:12px;
 right:12px;

 width:auto;

 z-index:100005;
 }

}


/* =========================================================
 SMALL MOBILE
========================================================= */

@media (max-width:500px){

 .cbx-logo-link{
 width:105px;
 flex-basis:105px;
 }

 .cbx-logo{
 width:105px !important;
 height:80px !important;
 }

 .cbx-result-item{
 min-height:64px;
 padding:8px 10px;
 }

 .cbx-result-image{
 width:44px;
 height:44px;
 flex-basis:44px;
 }

 .cbx-result-name{
 font-size:13px;
 }

}


/* =========================================================
 REDUCE MOTION
========================================================= */

@media (prefers-reduced-motion:reduce){

 #cbx-navbar-wrap *,
 #cbx-navbar-wrap *::before,
 #cbx-navbar-wrap *::after{
 animation:none !important;
 transition:none !important;
 }

}

/* =========================================================
 CELEBRITY BULAYE — PREMIUM MOBILE CONTROLS
 ========================================================= */

@media screen and (max-width: 900px) {

 /* ==============================
 HAMBURGER — NO BOX
 ============================== */

 #cbx-menu-btn,
 .cbx-menu-btn {
 position: absolute !important;

 top: 27px !important;
 right: 18px !important;

 width: 38px !important;
 height: 38px !important;

 display: flex !important;
 flex-direction: column !important;

 align-items: flex-end !important;
 justify-content: center !important;

 gap: 5px !important;

 background: transparent !important;
 border: none !important;
 border-radius: 0 !important;

 padding: 0 !important;
 margin: 0 !important;

 box-shadow: none !important;

 cursor: pointer !important;
 z-index: 999999 !important;
 }


 /* HAMBURGER LINES
 Small → Medium → Large */

 #cbx-menu-btn span,
 .cbx-menu-btn span {
 display: block !important;

 height: 2.5px !important;

 background: #B5121B !important;

 border-radius: 10px !important;

 padding: 0 !important;
 margin: 0 !important;

 transition:
 width .25s ease,
 transform .25s ease,
 opacity .25s ease !important;
 }

 /* Smallest */
 #cbx-menu-btn span:nth-child(1),
 .cbx-menu-btn span:nth-child(1) {
 width: 14px !important;
 }

 /* Medium */
 #cbx-menu-btn span:nth-child(2),
 .cbx-menu-btn span:nth-child(2) {
 width: 20px !important;
 }

 /* Largest */
 #cbx-menu-btn span:nth-child(3),
 .cbx-menu-btn span:nth-child(3) {
 width: 27px !important;
 }


 /* ==============================
 SEARCH AREA
 ============================== */

 .cbx-search-area {
 width: calc(100% - 24px) !important;

 margin: 3px 12px 14px !important;

 position: relative !important;

 z-index: 99995 !important;
 }


 /* SEARCH BOX */

 .cbx-search-form {
 width: 100% !important;
 height: 48px !important;

 display: flex !important;
 align-items: center !important;

 background: #ffffff !important;

 border: 1px solid #ded6c8 !important;

 border-radius: 14px !important;

 overflow: hidden !important;

 box-shadow:
 0 4px 15px rgba(0,0,0,.07),
 0 1px 3px rgba(181,18,27,.05) !important;

 transition:
 border-color .2s ease,
 box-shadow .2s ease !important;
 }


 /* SEARCH BOX FOCUS */

 .cbx-search-form:focus-within {
 border-color: #B5121B !important;

 box-shadow:
 0 5px 18px rgba(181,18,27,.12),
 0 0 0 3px rgba(181,18,27,.06) !important;
 }


 /* INPUT */

 .cbx-search-input {
 flex: 1 !important;

 width: 100% !important;
 height: 46px !important;

 border: none !important;
 outline: none !important;

 background: transparent !important;

 color: #222222 !important;

 font-family: Arial, sans-serif !important;
 font-size: 14px !important;

 padding: 0 15px !important;

 box-shadow: none !important;
 }

 .cbx-search-input::placeholder {
 color: #8a8a8a !important;
 opacity: 1 !important;
 }


 /* ==============================
 SEARCH BUTTON — ICON STYLE
 ============================== */

 .cbx-search-submit {
 width: 43px !important;
 min-width: 43px !important;
 height: 43px !important;

 margin-right: 3px !important;

 display: flex !important;
 align-items: center !important;
 justify-content: center !important;

 background: #B5121B !important;

 border: none !important;
 border-radius: 11px !important;

 padding: 0 !important;

 color: transparent !important;

 font-size: 0 !important;

 box-shadow:
 0 3px 8px rgba(181,18,27,.20) !important;

 cursor: pointer !important;
 }


 /* Search icon */

 .cbx-search-submit svg {
 width: 18px !important;
 height: 18px !important;

 stroke: #ffffff !important;
 stroke-width: 2.2 !important;

 display: block !important;
 }


 /* ==============================
 SEARCH SUGGESTIONS
 ============================== */

 .cbx-search-results {
 position: absolute !important;

 left: 0 !important;
 right: 0 !important;
 top: calc(100% + 7px) !important;

 width: 100% !important;

 background: #ffffff !important;

 border: 1px solid #e8e1d7 !important;

 border-radius: 12px !important;

 box-shadow:
 0 15px 35px rgba(0,0,0,.14) !important;

 overflow: hidden !important;

 z-index: 999999 !important;
 }


 /* ==============================
 MOBILE LOGO
 ============================== */

 .cbx-logo-link {
 width: 120px !important;
 height: 92px !important;

 display: flex !important;
 align-items: center !important;
 justify-content: center !important;

 margin: 0 auto !important;
 }

 .cbx-logo-link img {
 width: 110px !important;
 max-width: 110px !important;
 height: auto !important;

 object-fit: contain !important;
 }
}


/* =========================================
 SMALL PHONES
 ========================================= */

@media screen and (max-width: 480px) {

 #cbx-menu-btn,
 .cbx-menu-btn {
 right: 15px !important;
 top: 27px !important;
 }

 .cbx-search-area {
 width: calc(100% - 20px) !important;
 margin-left: 10px !important;
 margin-right: 10px !important;
 }

 .cbx-search-form {
 height: 47px !important;
 border-radius: 13px !important;
 }

 .cbx-search-input {
 height: 45px !important;
 font-size: 14px !important;
 padding-left: 14px !important;
 }

 .cbx-search-submit {
 width: 42px !important;
 min-width: 42px !important;
 height: 42px !important;
 }
}


/* =========================================
 EXTRA SMALL PHONES
 ========================================= */

@media screen and (max-width: 360px) {

 #cbx-menu-btn,
 .cbx-menu-btn {
 right: 11px !important;
 top: 26px !important;
 }

 .cbx-logo-link img {
 width: 100px !important;
 max-width: 100px !important;
 }
}

</style>


<script>

(function(){

 "use strict";


 /* =======================================================
 ELEMENTS
 ======================================================== */

 const root = document.getElementById("cbx-navbar-wrap");

 if(!root) return;

 const searchInput = document.getElementById("cbx-search-input");
 const searchForm = document.getElementById("cbx-search-form");

 const searchResults = document.getElementById("cbx-search-results");
 const resultsList = document.getElementById("cbx-results-list");

 const resultCount = document.getElementById("cbx-result-count");
 const viewAll = document.getElementById("cbx-view-all");

 const dropdownLayer = document.getElementById("cbx-dropdown-layer");

 const menuButton = document.getElementById("cbx-menu-btn");
 const mobileDrawer = document.getElementById("cbx-mobile-drawer");
 const mobileOverlay = document.getElementById("cbx-mobile-overlay");
 const mobileClose = document.getElementById("cbx-mobile-close");

 const mobileSearchButton =
 document.getElementById("cbx-mobile-search-btn");


 /* =======================================================
 DROPDOWNS
 ======================================================== */

 const categoryItems =
 root.querySelectorAll(".cbx-category-item");

 const dropdowns =
 root.querySelectorAll(".cbx-dropdown");


 let activeDropdown = null;


 function closeDropdowns(){

 dropdowns.forEach(function(dropdown){
 dropdown.classList.remove("cbx-open");
 });

 activeDropdown = null;
 }


 function positionDropdown(item, dropdown){

 const rect = item.getBoundingClientRect();

 const viewportWidth = window.innerWidth;

 const dropdownWidth =
 Math.min(
 780,
 viewportWidth - 32
 );

 let left =
 rect.left +
 (rect.width / 2) -
 (dropdownWidth / 2);

 const minimumLeft = 16;

 const maximumLeft =
 viewportWidth -
 dropdownWidth -
 16;

 if(left < minimumLeft){
 left = minimumLeft;
 }

 if(left > maximumLeft){
 left = maximumLeft;
 }

 let top = rect.bottom + 2;

 const dropdownHeight =
 Math.min(
 dropdown.offsetHeight || 400,
 window.innerHeight - 150
 );

 if(
 top + dropdownHeight >
 window.innerHeight - 15
 ){

 top =
 Math.max(
 15,
 rect.top - dropdownHeight - 2
 );

 }

 dropdown.style.left =
 Math.round(left) + "px";

 dropdown.style.top =
 Math.round(top) + "px";

 }


 categoryItems.forEach(function(item){

 const menuName =
 item.getAttribute("data-menu");

 const dropdown =
 root.querySelector(
 '.cbx-dropdown[data-dropdown="' +
 menuName +
 '"]'
 );

 if(!dropdown) return;


 item.addEventListener(
 "mouseenter",
 function(){

 if(window.innerWidth <= 900) return;

 closeDropdowns();

 dropdown.classList.add("cbx-open");

 activeDropdown = dropdown;

 positionDropdown(
 item,
 dropdown
 );

 }
 );


 item.addEventListener(
 "mouseleave",
 function(){

 if(window.innerWidth <= 900) return;

 setTimeout(function(){

 if(
 !item.matches(":hover") &&
 !dropdown.matches(":hover")
 ){

 dropdown.classList.remove("cbx-open");

 if(activeDropdown === dropdown){
 activeDropdown = null;
 }

 }

 },120);

 }
 );


 dropdown.addEventListener(
 "mouseleave",
 function(){

 if(window.innerWidth <= 900) return;

 setTimeout(function(){

 if(
 !item.matches(":hover") &&
 !dropdown.matches(":hover")
 ){

 dropdown.classList.remove("cbx-open");

 if(activeDropdown === dropdown){
 activeDropdown = null;
 }

 }

 },120);

 }
 );

 });


 window.addEventListener(
 "resize",
 function(){

 if(activeDropdown){

 const menuName =
 activeDropdown.getAttribute(
 "data-dropdown"
 );

 const item =
 root.querySelector(
 '.cbx-category-item[data-menu="' +
 menuName +
 '"]'
 );

 if(item){

 positionDropdown(
 item,
 activeDropdown
 );

 }

 }

 }
 );


 window.addEventListener(
 "scroll",
 function(){

 if(activeDropdown){

 const menuName =
 activeDropdown.getAttribute(
 "data-dropdown"
 );

 const item =
 root.querySelector(
 '.cbx-category-item[data-menu="' +
 menuName +
 '"]'
 );

 if(item){

 positionDropdown(
 item,
 activeDropdown
 );

 }

 }

 },
 true
 );


 document.addEventListener(
 "click",
 function(event){

 if(
 !event.target.closest(
 "#cbx-navbar-wrap"
 )
 ){

 closeDropdowns();

 }

 }
 );


 /* =======================================================
 SEARCH HELPERS
 ======================================================== */


 function escapeHTML(value){

 return String(value || "")
 .replace(/&/g,"&amp;")
 .replace(/</g,"&lt;")
 .replace(/>/g,"&gt;")
 .replace(/"/g,"&quot;")
 .replace(/'/g,"&#039;");

 }


 function stripHTML(value){

 const temp =
 document.createElement("div");

 temp.innerHTML =
 value || "";

 return (
 temp.textContent ||
 temp.innerText ||
 ""
 ).trim();

 }


 function getSearchTitle(item){

 if(
 typeof item.title === "string"
 ){

 return stripHTML(
 item.title
 );

 }

 if(
 item.title &&
 typeof item.title.rendered === "string"
 ){

 return stripHTML(
 item.title.rendered
 );

 }

 return "View Result";

 }


 function scoreResult(title, query){

 const t =
 title.toLowerCase().trim();

 const q =
 query.toLowerCase().trim();

 if(!t || !q) return 0;

 if(t === q){
 return 1000;
 }

 if(t.startsWith(q)){
 return 850;
 }

 const words =
 t.split(/\s+/);

 if(
 words.some(function(word){
 return word.startsWith(q);
 })
 ){
 return 700;
 }

 if(t.includes(q)){
 return 550;
 }

 return 100;

 }


 function highlightText(text, query){

 const safe =
 escapeHTML(text);

 const safeQuery =
 escapeHTML(query);

 if(!safeQuery) return safe;

 const regex =
 new RegExp(
 "(" +
 safeQuery.replace(
 /[.*+?^${}()|[\]\\]/g,
 "\\$&"
 ) +
 ")",
 "ig"
 );

 return safe.replace(
 regex,
 "<mark>$1</mark>"
 );

 }


 /* =======================================================
 GET IMAGE + CATEGORY FROM POST/PAGE
 ======================================================== */

 async function getPostDetails(item){

 try{

 const id =
 encodeURIComponent(
 item.id
 );

 let endpoint = "";

 /*
 * WordPress search returns:
 * type = post
 * subtype = post/page
 *
 * Both are handled here.
 */

 if(item.subtype === "page"){

 endpoint =
 "/wp-json/wp/v2/pages/" +
 id +
 "?_embed";

 }else{

 endpoint =
 "/wp-json/wp/v2/posts/" +
 id +
 "?_embed";

 }


 const response =
 await fetch(
 endpoint,
 {
 credentials:"same-origin"
 }
 );


 if(!response.ok){
 return {};
 }


 const data =
 await response.json();


 let image = "";


 /* FEATURED IMAGE */

 if(
 data._embedded &&
 data._embedded["wp:featuredmedia"] &&
 data._embedded["wp:featuredmedia"][0]
 ){

 const media =
 data._embedded["wp:featuredmedia"][0];

 image =
 media.source_url ||
 (
 media.media_details &&
 media.media_details.sizes &&
 media.media_details.sizes.medium &&
 media.media_details.sizes.medium.source_url
 ) ||
 "";

 }


 /* CATEGORY */

 let category = "";


 if(
 data._embedded &&
 data._embedded["wp:term"]
 ){

 const terms =
 data._embedded["wp:term"];

 for(
 let i = 0;
 i < terms.length;
 i++
 ){

 const group =
 terms[i];

 if(!Array.isArray(group)) continue;

 const categoryTerm =
 group.find(function(term){

 return (
 term.taxonomy === "category"
 );

 });

 if(categoryTerm){

 category =
 categoryTerm.name;

 break;

 }

 }

 }


 if(!category){

 if(item.subtype === "page"){
 category = "Page";
 }else{
 category = "Celebrity";
 }

 }


 return {
 image:image,
 category:stripHTML(category)
 };


 }catch(error){

 return {};

 }

 }


 /* =======================================================
 SEARCH
 ======================================================== */

 let searchTimer = null;

 let currentSearchToken = 0;


 async function searchWebsite(query){

 query =
 String(query || "").trim();


 if(query.length < 2){

 searchResults.classList.remove(
 "cbx-visible"
 );

 resultsList.innerHTML = "";

 resultCount.textContent = "";

 return;

 }


 const token =
 ++currentSearchToken;


 searchResults.classList.add(
 "cbx-visible"
 );


 resultsList.innerHTML =
 '<div class="cbx-search-loading">' +
 'Searching Celebrity Bulaye...' +
 '</div>';


 resultCount.textContent = "";


 viewAll.href =
 "/?s=" +
 encodeURIComponent(query);


 try{

 /*
 * Search POSTS + PAGES separately.
 * This makes the search more reliable.
 */

 const base =
 "/wp-json/wp/v2/search";


 const postURL =
 base +
 "?search=" +
 encodeURIComponent(query) +
 "&type=post" +
 "&subtype=post" +
 "&per_page=20";


 const pageURL =
 base +
 "?search=" +
 encodeURIComponent(query) +
 "&type=post" +
 "&subtype=page" +
 "&per_page=10";


 const responses =
 await Promise.all([
 fetch(
 postURL,
 {
 credentials:"same-origin"
 }
 ),
 fetch(
 pageURL,
 {
 credentials:"same-origin"
 }
 )
 ]);


 const postResponse =
 responses[0];

 const pageResponse =
 responses[1];


 let posts = [];
 let pages = [];


 if(postResponse.ok){

 posts =
 await postResponse.json();

 }


 if(pageResponse.ok){

 pages =
 await pageResponse.json();

 }


 if(token !== currentSearchToken){
 return;
 }


 /*
 * Combine results.
 */

 const combined =
 posts.concat(pages);


 /*
 * Remove duplicate IDs.
 */

 const unique = [];

 const seen = new Set();


 combined.forEach(function(item){

 const key =
 String(item.type) +
 "-" +
 String(item.id);


 if(!seen.has(key)){

 seen.add(key);

 unique.push(item);

 }

 });


 /*
 * Convert title correctly.
 */

 const prepared =
 unique.map(function(item){

 const title =
 getSearchTitle(item);

 return {
 item:item,
 title:title,
 score:scoreResult(
 title,
 query
 )
 };

 });


 /*
 * Best matches first.
 */

 prepared.sort(function(a,b){

 if(b.score !== a.score){

 return b.score - a.score;

 }

 return a.title.localeCompare(
 b.title
 );

 });


 /*
 * Maximum 8 live results.
 */

 const selected =
 prepared.slice(0,8);


 if(!selected.length){

 resultsList.innerHTML =
 '<div class="cbx-search-empty">' +
 'No matching celebrity or page found.' +
 '</div>';

 resultCount.textContent = "0";

 viewAll.style.display = "none";

 return;

 }


 resultCount.textContent =
 selected.length;


 viewAll.style.display =
 "flex";


 /*
 * Fetch featured images/category
 * for all selected results.
 */

 const detailResults =
 await Promise.all(
 selected.map(function(result){

 return getPostDetails(
 result.item
 );

 })
 );


 if(token !== currentSearchToken){
 return;
 }


 resultsList.innerHTML = "";


 selected.forEach(
 function(result,index){

 const detail =
 detailResults[index] || {};


 const item =
 result.item;


 const title =
 result.title;


 const url =
 item.url ||
 "/?s=" +
 encodeURIComponent(title);


 const category =
 detail.category ||
 (
 item.subtype === "page"
 ? "Page"
 : "Celebrity"
 );


 const row =
 document.createElement("a");


 row.className =
 "cbx-result-item";


 row.href =
 url;


 /*
 * IMAGE
 */

 const imageBox =
 document.createElement("div");


 imageBox.className =
 "cbx-result-image";


 if(detail.image){

 const image =
 document.createElement("img");


 image.src =
 detail.image;

 image.alt =
 title;

 image.loading =
 "lazy";


 image.onerror =
 function(){

 image.remove();

 imageBox.textContent =
 title
 .charAt(0)
 .toUpperCase();

 };


 imageBox.appendChild(
 image
 );

 }else{

 imageBox.textContent =
 title
 .charAt(0)
 .toUpperCase();

 }


 /*
 * CONTENT
 */

 const content =
 document.createElement("div");


 content.className =
 "cbx-result-content";


 const name =
 document.createElement("div");


 name.className =
 "cbx-result-name";


 name.innerHTML =
 highlightText(
 title,
 query
 );


 const meta =
 document.createElement("div");


 meta.className =
 "cbx-result-meta";


 meta.textContent =
 category;


 content.appendChild(
 name
 );

 content.appendChild(
 meta
 );


 /*
 * ARROW
 */

 const arrow =
 document.createElement("div");


 arrow.className =
 "cbx-result-arrow";


 arrow.innerHTML =
 "→";


 row.appendChild(
 imageBox
 );

 row.appendChild(
 content
 );

 row.appendChild(
 arrow
 );


 resultsList.appendChild(
 row
 );

 }
 );


 }catch(error){

 if(token !== currentSearchToken){
 return;
 }


 resultsList.innerHTML =
 '<div class="cbx-search-empty">' +
 'Search is temporarily unavailable. Please press Enter to search.' +
 '</div>';

 resultCount.textContent = "";

 viewAll.style.display =
 "flex";

 }

 }


 /* =======================================================
 INPUT EVENT
 ======================================================== */

 if(searchInput){

 searchInput.addEventListener(
 "input",
 function(){

 const query =
 this.value.trim();


 clearTimeout(
 searchTimer
 );


 if(query.length < 2){

 searchResults.classList.remove(
 "cbx-visible"
 );

 resultsList.innerHTML = "";

 resultCount.textContent = "";

 return;

 }


 searchTimer =
 setTimeout(
 function(){

 searchWebsite(
 query
 );

 },
 300
 );

 }
 );


 searchInput.addEventListener(
 "focus",
 function(){

 if(
 this.value.trim().length >= 2
 ){

 searchResults.classList.add(
 "cbx-visible"
 );

 }

 }
 );

 }


 /* =======================================================
 SEARCH FORM
 ======================================================== */

 if(searchForm){

 searchForm.addEventListener(
 "submit",
 function(){

 const query =
 searchInput.value.trim();


 if(!query){

 return;

 }

 /*
 * Normal WordPress search:
 * /?s=salman
 */

 searchForm.action = "/";

 }
 );

 }


 /* =======================================================
 CLOSE SEARCH OUTSIDE
 ======================================================== */

 document.addEventListener(
 "click",
 function(event){

 if(
 !event.target.closest(
 ".cbx-search-area"
 )
 ){

 if(searchResults){

 searchResults.classList.remove(
 "cbx-visible"
 );

 }

 }

 }
 );


 /* =======================================================
 MOBILE DRAWER
 ======================================================== */

 function openMobileMenu(){

 mobileDrawer.classList.add(
 "cbx-active"
 );

 mobileOverlay.classList.add(
 "cbx-active"
 );

 menuButton.classList.add(
 "cbx-open"
 );

 menuButton.setAttribute(
 "aria-expanded",
 "true"
 );

 document.body.style.overflow =
 "hidden";

 }


 function closeMobileMenu(){

 mobileDrawer.classList.remove(
 "cbx-active"
 );

 mobileOverlay.classList.remove(
 "cbx-active"
 );

 menuButton.classList.remove(
 "cbx-open"
 );

 menuButton.setAttribute(
 "aria-expanded",
 "false"
 );

 document.body.style.overflow =
 "";

 }


 if(menuButton){

 menuButton.addEventListener(
 "click",
 function(){

 if(
 mobileDrawer.classList.contains(
 "cbx-active"
 )
 ){

 closeMobileMenu();

 }else{

 openMobileMenu();

 }

 }
 );

 }


 if(mobileClose){

 mobileClose.addEventListener(
 "click",
 closeMobileMenu
 );

 }


 if(mobileOverlay){

 mobileOverlay.addEventListener(
 "click",
 closeMobileMenu
 );

 }


 /*
 * Close mobile menu after clicking link.
 */

 const mobileLinks =
 root.querySelectorAll(
 ".cbx-mobile-nav a"
 );


 mobileLinks.forEach(
 function(link){

 link.addEventListener(
 "click",
 closeMobileMenu
 );

 }
 );


 /* =======================================================
 MOBILE SEARCH BUTTON
 ======================================================== */

 if(mobileSearchButton){

 mobileSearchButton.addEventListener(
 "click",
 function(){

 /*
 * Open drawer and focus search.
 */

 openMobileMenu();

 setTimeout(
 function(){

 const input =
 root.querySelector(
 ".cbx-mobile-search input"
 );

 if(input){
 input.focus();
 }

 },
 350
 );

 }
 );

 }


 /* =======================================================
 ESC KEY
 ======================================================== */

 document.addEventListener(
 "keydown",
 function(event){

 if(event.key === "Escape"){

 closeDropdowns();

 closeMobileMenu();

 if(searchResults){

 searchResults.classList.remove(
 "cbx-visible"
 );

 }

 }

 }
 );


})();

