[{"id":"8964482","elType":"section","settings":{"hover_parallax":[{"layer_position_vr":{"unit":"%","size":30},"layer_position_hr":{"unit":"%","size":40},"_id":"a85ddbc"},{"layer_position_vr":{"unit":"%","size":60},"layer_position_hr":{"unit":"%","size":20},"_id":"2edebcd"}]},"elements":[{"id":"e775d4f","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"d36d208","elType":"widget","settings":{"html":"<style>
/* =========================================
   CELEBRITY BULAYE - ABOUT US HERO
========================================= */

.cb-about-hero {
    width: 100vw !important;
    max-width: 100vw !important;
    margin-left: calc(50% - 50vw) !important;
    margin-right: calc(50% - 50vw) !important;

    min-height: 570px;
    position: relative;
    display: flex;
    align-items: center;
    overflow: hidden;
    box-sizing: border-box;

    /* Celebrity Bulaye website image */
    background-image:
        linear-gradient(
            90deg,
            rgba(0,0,0,0.82) 0%,
            rgba(0,0,0,0.65) 38%,
            rgba(0,0,0,0.28) 72%,
            rgba(0,0,0,0.45) 100%
        ),
        url("https://celebritybulaye.in/wp-content/uploads/2023/08/kishwar-merchant.jpg");

    background-size: cover;
    background-position: center 30%;
    background-repeat: no-repeat;
}

/* Red cinematic glow */
.cb-about-hero::before {
    content: "";
    position: absolute;
    width: 420px;
    height: 420px;
    right: -130px;
    bottom: -180px;
    background: rgba(181,18,27,0.28);
    filter: blur(90px);
    border-radius: 50%;
    pointer-events: none;
}

/* Gold vertical accent */
.cb-about-hero::after {
    content: "";
    position: absolute;
    left: 6%;
    top: 18%;
    width: 2px;
    height: 64%;
    background: #C9A227;
    opacity: 0.9;
}

/* CONTENT */

.cb-about-hero-content {
    position: relative;
    z-index: 2;
    width: 100%;
    max-width: 1250px;
    margin: 0 auto;
    padding: 100px 6%;
    box-sizing: border-box;
}

.cb-about-hero-eyebrow {
    display: flex;
    align-items: center;
    gap: 13px;

    margin-bottom: 20px;

    font-family: Arial, sans-serif;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 4px;
    text-transform: uppercase;

    color: #E5C766;
}

.cb-about-hero-eyebrow::before {
    content: "";
    width: 42px;
    height: 1px;
    background: #E5C766;
}

.cb-about-hero h1 {
    max-width: 720px;

    margin: 0;

    font-family:
        "Playfair Display",
        Georgia,
        "Times New Roman",
        serif;

    font-size: clamp(48px, 6vw, 82px);
    line-height: 1.02;
    font-weight: 500;

    color: #FFFFFF;
    letter-spacing: -1.5px;
}

.cb-about-hero h1 span {
    color: #E5C766;
}

.cb-about-hero-description {
    max-width: 600px;

    margin: 25px 0 32px;

    font-family: Arial, sans-serif;
    font-size: 17px;
    line-height: 1.75;

    color: rgba(255,255,255,0.82);
}

/* BUTTON */

.cb-about-hero-btn {
    display: inline-flex;
    align-items: center;
    gap: 14px;

    padding: 15px 28px;

    background: #B5121B;
    color: #FFFFFF;

    text-decoration: none;

    font-family: Arial, sans-serif;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 1.4px;
    text-transform: uppercase;

    transition: all 0.3s ease;
}

.cb-about-hero-btn span {
    font-size: 17px;
    line-height: 1;
    transition: transform 0.3s ease;
}

.cb-about-hero-btn:hover {
    background: #FFFFFF;
    color: #B5121B;
}

.cb-about-hero-btn:hover span {
    transform: translateX(5px);
}

/* SMALL BOTTOM LABEL */

.cb-about-hero-bottom {
    position: absolute;
    z-index: 3;

    right: 6%;
    bottom: 38px;

    display: flex;
    align-items: center;
    gap: 12px;

    font-family: Arial, sans-serif;
    font-size: 10px;
    letter-spacing: 2px;
    text-transform: uppercase;

    color: rgba(255,255,255,0.75);
}

.cb-about-hero-bottom::before {
    content: "";
    width: 35px;
    height: 1px;
    background: #C9A227;
}


/* =========================================
   TABLET
========================================= */

@media (max-width: 900px) {

    .cb-about-hero {
        min-height: 500px;

        background-position: 65% center;
    }

    .cb-about-hero-content {
        padding: 85px 8%;
    }

    .cb-about-hero h1 {
        font-size: clamp(46px, 8vw, 68px);
    }

    .cb-about-hero::after {
        left: 4%;
    }
}


/* =========================================
   MOBILE
========================================= */

@media (max-width: 600px) {

    .cb-about-hero {
        min-height: 570px;

        background-position: 68% center;

        background-image:
            linear-gradient(
                90deg,
                rgba(0,0,0,0.82) 0%,
                rgba(0,0,0,0.68) 55%,
                rgba(0,0,0,0.40) 100%
            ),
            url("https://celebritybulaye.in/wp-content/uploads/2023/08/kishwar-merchant.jpg");
    }

    .cb-about-hero-content {
        padding: 90px 24px 80px;
    }

    .cb-about-hero::after {
        left: 18px;
        top: 15%;
        height: 70%;
    }

    .cb-about-hero-eyebrow {
        font-size: 10px;
        letter-spacing: 2.5px;
        margin-left: 12px;
    }

    .cb-about-hero h1 {
        margin-left: 12px;
        font-size: 48px;
        line-height: 1.05;
        letter-spacing: -0.8px;
    }

    .cb-about-hero-description {
        margin-left: 12px;
        font-size: 14px;
        line-height: 1.7;
        max-width: 470px;
    }

    .cb-about-hero-btn {
        margin-left: 12px;
        padding: 14px 22px;
        font-size: 11px;
    }

    .cb-about-hero-bottom {
        display: none;
    }
}
</style>


<section class="cb-about-hero">

    <div class="cb-about-hero-content">

        <div class="cb-about-hero-eyebrow">
            About Celebrity Bulaye
        </div>

        <h1>
            Bringing <span>Star Power</span><br>
            To Your Moments
        </h1>

        <p class="cb-about-hero-description">
            We connect extraordinary events, brands and celebrations
            with the celebrities who make them truly unforgettable.
        </p>

        <a
            href="/book-celebrity/"
            class="cb-about-hero-btn"
        >
            Explore Celebrities
            <span>→</span>
        </a>

    </div>

    <div class="cb-about-hero-bottom">
        Your Gateway To Celebrity Experiences
    </div>

</section>"},"elements":[],"widgetType":"html"}],"isInner":false}],"isInner":false},{"id":"79ccf5d","elType":"section","settings":{"hover_parallax":[{"layer_position_vr":{"unit":"%","size":30},"layer_position_hr":{"unit":"%","size":40},"_id":"e275fbb"},{"layer_position_vr":{"unit":"%","size":60},"layer_position_hr":{"unit":"%","size":20},"_id":"bf15574"}]},"elements":[{"id":"7b5ef9c","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"7c0a022","elType":"widget","settings":{"html":"<style>
/* ================================
   CELEBRITY BULAYE - ABOUT SECTION
   ================================ */

.cb-about-story {
    width: 100vw !important;
    max-width: 100vw !important;
    margin-left: calc(50% - 50vw) !important;
    margin-right: calc(50% - 50vw) !important;
    background: #FCFAF6;
    padding: 95px 6vw 100px;
    box-sizing: border-box;
    overflow: hidden;
}

.cb-about-inner {
    width: 100%;
    max-width: 1280px;
    margin: 0 auto;
}

/* ---------- HEADER ---------- */

.cb-about-heading {
    text-align: center;
    margin-bottom: 65px;
}

.cb-about-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    font-family: Inter, Arial, sans-serif;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: #B5121B;
    margin-bottom: 18px;
}

.cb-about-eyebrow::before,
.cb-about-eyebrow::after {
    content: "";
    width: 32px;
    height: 1px;
    background: #C9A227;
}

.cb-about-heading h2 {
    margin: 0;
    font-family: "Playfair Display", Georgia, serif;
    font-size: clamp(38px, 5vw, 64px);
    line-height: 1.08;
    font-weight: 500;
    color: #171717;
}

.cb-about-heading h2 span {
    color: #B5121B;
    font-style: italic;
}

/* ---------- INTRO ---------- */

.cb-about-intro {
    max-width: 1050px;
    margin: 0 auto 58px;
    text-align: center;
}

.cb-about-intro h3 {
    margin: 0 0 24px;
    font-family: "Playfair Display", Georgia, serif;
    font-size: clamp(25px, 3vw, 38px);
    line-height: 1.25;
    font-weight: 500;
    color: #171717;
}

.cb-about-intro h3 span {
    color: #B5121B;
}

.cb-about-intro p {
    margin: 0 auto;
    max-width: 900px;
    font-family: Inter, Arial, sans-serif;
    font-size: 17px;
    line-height: 1.9;
    color: #666;
}

/* ---------- IMAGE ---------- */

.cb-about-image-wrap {
    width: 100%;
    margin: 55px auto;
    position: relative;
}

.cb-about-image-frame {
    width: 100%;
    height: 470px;
    overflow: hidden;
    position: relative;
    background: #eee;
    border: 1px solid #E8E4DC;
}

.cb-about-image-frame::before {
    content: "";
    position: absolute;
    inset: 12px;
    border: 1px solid rgba(201,162,39,0.55);
    z-index: 2;
    pointer-events: none;
}

.cb-about-image-frame img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    object-position: center center;
    display: block;
    transition: transform 0.7s ease;
}

.cb-about-image-frame:hover img {
    transform: scale(1.035);
}

/* ---------- CONTENT ---------- */

.cb-about-content {
    max-width: 1050px;
    margin: 0 auto;
}

.cb-about-content p {
    margin: 0 0 28px;
    font-family: Inter, Arial, sans-serif;
    font-size: 17px;
    line-height: 1.95;
    color: #5F5F5F;
}

.cb-about-content p:last-child {
    margin-bottom: 0;
}

/* ---------- SECOND IMAGE ---------- */

.cb-about-image-small {
    width: 100%;
    margin: 58px auto;
    display: grid;
    grid-template-columns: 1fr;
}

.cb-about-image-small .cb-about-image-frame {
    height: 430px;
}

/* ---------- BOTTOM ACCENT ---------- */

.cb-about-bottom {
    max-width: 1050px;
    margin: 62px auto 0;
    padding-top: 28px;
    border-top: 1px solid #E8E4DC;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 30px;
