/* =====================================================
   CELEBRITY BULAYE — PREMIUM GALLERY
   WHITE / RED / GOLD
   FULL WIDTH EDGE TO EDGE
===================================================== */

.cb-gallery {
    width: 100vw !important;
    max-width: 100vw !important;
    margin-left: calc(50% - 50vw) !important;
    margin-right: calc(50% - 50vw) !important;
    background: #FCFAF6;
    padding: 100px 5vw 110px;
    box-sizing: border-box;
    overflow: hidden;
}

.cb-gallery-inner {
    width: 100%;
    max-width: 1380px;
    margin: 0 auto;
}

/* ================= HEADER ================= */

.cb-gallery-header {
    text-align: center;
    margin-bottom: 58px;
}

.cb-gallery-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    font-family: Inter, Arial, sans-serif;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: #B5121B;
    margin-bottom: 18px;
}

.cb-gallery-eyebrow::before,
.cb-gallery-eyebrow::after {
    content: "";
    width: 34px;
    height: 1px;
    background: #C9A227;
}

.cb-gallery-header h2 {
    margin: 0;
    font-family: "Playfair Display", Georgia, serif;
    font-size: clamp(38px, 5vw, 64px);
    line-height: 1.08;
    font-weight: 500;
    color: #171717;
}

.cb-gallery-header h2 span {
    color: #B5121B;
    font-style: italic;
}

.cb-gallery-header p {
    max-width: 680px;
    margin: 20px auto 0;
    font-family: Inter, Arial, sans-serif;
    font-size: 16px;
    line-height: 1.8;
    color: #707070;
}


/* ================= GALLERY GRID ================= */

.cb-gallery-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    grid-auto-rows: 280px;
    gap: 16px;
}

/* Individual gallery item */

.cb-gallery-item {
    position: relative;
    overflow: hidden;
    background: #e9e5df;
    cursor: pointer;
    border: 1px solid #E8E4DC;
}

/* Tall feature */

.cb-gallery-item.tall {
    grid-row: span 2;
}

/* Wide feature */

.cb-gallery-item.wide {
    grid-column: span 2;
}


/* ================= IMAGE ================= */

.cb-gallery-item img {
    width: 100% !important;
    height: 100% !important;
    display: block;
    object-fit: cover !important;
    object-position: center center;
    transition:
        transform 0.7s cubic-bezier(.2,.7,.2,1),
        filter 0.5s ease;
}

.cb-gallery-item:hover img {
    transform: scale(1.055);
    filter: brightness(0.82);
}


/* ================= OVERLAY ================= */

.cb-gallery-overlay {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: flex-end;
    padding: 24px;
    background:
        linear-gradient(
            to top,
            rgba(0,0,0,0.68) 0%,
            rgba(0,0,0,0.12) 45%,
            transparent 75%
        );
    opacity: 0;
    transition: opacity 0.4s ease;
}

.cb-gallery-item:hover .cb-gallery-overlay {
    opacity: 1;
}

.cb-gallery-overlay-content {
    transform: translateY(10px);
    transition: transform 0.4s ease;
}

.cb-gallery-item:hover .cb-gallery-overlay-content {
    transform: translateY(0);
}

.cb-gallery-label {
    font-family: Inter, Arial, sans-serif;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: #E5C766;
    margin-bottom: 5px;
}

.cb-gallery-title {
    font-family: "Playfair Display", Georgia, serif;
    font-size: 21px;
    color: #FFFFFF;
}


/* ================= GOLD CORNER ================= */

.cb-gallery-item::after {
    content: "";
    position: absolute;
    right: 12px;
    top: 12px;
    width: 28px;
    height: 28px;
    border-top: 1px solid rgba(229,199,102,0.9);
    border-right: 1px solid rgba(229,199,102,0.9);
    opacity: 0;
    transition: opacity 0.35s ease;
    pointer-events: none;
}

.cb-gallery-item:hover::after {
    opacity: 1;
}


/* ================= BOTTOM ================= */

.cb-gallery-bottom {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 20px;
    margin-top: 52px;
}

.cb-gallery-line {
    width: 65px;
    height: 1px;
    background: #C9A227;
}

.cb-gallery-bottom span {
    font-family: Inter, Arial, sans-serif;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: #777;
}


/* ================= LIGHTBOX ================= */

.cb-gallery-lightbox {
    position: fixed;
    inset: 0;
    background: rgba(10,10,10,0.94);
    z-index: 999999;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 30px;
}

.cb-gallery-lightbox.active {
    display: flex;
}

.cb-gallery-lightbox img {
    max-width: 92vw;
    max-height: 90vh;
    width: auto !important;
    height: auto !important;
    object-fit: contain !important;
    box-shadow: 0 20px 70px rgba(0,0,0,0.45);
}

.cb-gallery-close {
    position: fixed;
    top: 22px;
    right: 28px;
    width: 44px;
    height: 44px;
    border: 1px solid rgba(229,199,102,0.7);
    background: rgba(255,255,255,0.08);
    color: #FFFFFF;
    font-size: 25px;
    line-height: 40px;
    text-align: center;
    cursor: pointer;
    z-index: 10;
    transition: all 0.25s ease;
}

.cb-gallery-close:hover {
    background: #B5121B;
    border-color: #B5121B;
}


/* ================= TABLET ================= */

@media (max-width: 1000px) {

    .cb-gallery {
        padding: 80px 4vw 90px;
    }

    .cb-gallery-grid {
        grid-template-columns: repeat(3, 1fr);
        grid-auto-rows: 260px;
    }

    .cb-gallery-item.wide {
        grid-column: span 2;
    }
}


/* ================= MOBILE ================= */

@media (max-width: 650px) {

    .cb-gallery {
        padding: 65px 18px 75px;
    }

    .cb-gallery-header {
        margin-bottom: 40px;
    }

    .cb-gallery-eyebrow {
        font-size: 9px;
        letter-spacing: 2px;
        gap: 8px;
    }

    .cb-gallery-eyebrow::before,
    .cb-gallery-eyebrow::after {
        width: 20px;
    }

    .cb-gallery-header h2 {
        font-size: 38px;
    }

    .cb-gallery-header p {
        font-size: 14px;
        line-height: 1.75;
    }

    .cb-gallery-grid {
        grid-template-columns: repeat(2, 1fr);
        grid-auto-rows: 250px;
        gap: 10px;
    }

    .cb-gallery-item.tall {
        grid-row: span 2;
    }

    .cb-gallery-item.wide {
        grid-column: span 2;
    }

    .cb-gallery-overlay {
        opacity: 1;
        padding: 14px;
    }

    .cb-gallery-overlay-content {
        transform: none;
    }

    .cb-gallery-title {
        font-size: 16px;
    }

    .cb-gallery-label {
        font-size: 8px;
    }

    .cb-gallery-lightbox {
        padding: 15px;
    }

    .cb-gallery-lightbox img {
        max-width: 95vw;
        max-height: 85vh;
    }
}
</style>


