  align-items:center;
  gap:12px;
  color:#e5c766;
  font-family:Inter,Arial,sans-serif;
  font-size:12px;
  font-weight:700;
  letter-spacing:2.5px;
  text-transform:uppercase;
  margin-bottom:18px;
}

.cb-final-cta-eyebrow:before,
.cb-final-cta-eyebrow:after{
  content:"";
  width:35px;
  height:1px;
  background:#e5c766;
}

.cb-final-cta-title{
  margin:0 auto 18px;
  max-width:800px;
  color:#fff;
  font-family:Georgia,"Times New Roman",serif;
  font-size:clamp(34px,4.5vw,58px);
  line-height:1.08;
  font-weight:500;
}

.cb-final-cta-title span{
  color:#e5c766;
}

.cb-final-cta-text{
  max-width:650px;
  margin:0 auto 32px;
  color:rgba(255,255,255,.86);
  font-family:Inter,Arial,sans-serif;
  font-size:16px;
  line-height:1.75;
}

.cb-final-cta-button{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:12px;
  padding:15px 30px;
  background:#fff;
  color:#8e0e16 !important;
  text-decoration:none !important;
  border-radius:50px;
  font-family:Inter,Arial,sans-serif;
  font-size:14px;
  font-weight:700;
  letter-spacing:.3px;
  transition:all .3s ease;
  box-shadow:0 8px 25px rgba(0,0,0,.16);
}

.cb-final-cta-button:hover{
  background:#e5c766;
  color:#171717 !important;
  transform:translateY(-3px);
  box-shadow:0 12px 30px rgba(0,0,0,.22);
}

.cb-final-cta-note{
  margin-top:22px;
  color:rgba(255,255,255,.58);
  font-family:Inter,Arial,sans-serif;
  font-size:12px;
  letter-spacing:.5px;
}

/* Mobile */
@media(max-width:767px){
  .cb-final-cta{
    padding:45px 16px;
  }

  .cb-final-cta-box{
    padding:50px 22px;
    border-radius:22px;
  }

  .cb-final-cta-eyebrow{
    font-size:10px;
    letter-spacing:1.8px;
  }

  .cb-final-cta-eyebrow:before,
  .cb-final-cta-eyebrow:after{
    width:20px;
  }

  .cb-final-cta-title{
    font-size:34px;
  }

  .cb-final-cta-text{
    font-size:14px;
    line-height:1.7;
  }

  .cb-final-cta-button{
    width:100%;
    max-width:260px;
  }
}
</style>

<section class="cb-final-cta">
  <div class="cb-final-cta-box">
    <div class="cb-final-cta-inner">

      <div class="cb-final-cta-eyebrow">
        Celebrity Bulaye
      </div>

      <h2 class="cb-final-cta-title">
        Ready to Make Your Event <span>Unforgettable?</span>
      </h2>

      <p class="cb-final-cta-text">
        From celebrity appearances to brand endorsements and special events,
        let us help you bring the right star to your occasion.
      </p>

      <a href="/contact-us/" class="cb-final-cta-button">
        Make an Inquiry
        <span>→</span>
      </a>

      <div class="cb-final-cta-note">
        Let's create something extraordinary together.
      </div>

    </div>
  </div>
</section>"},"elements":[],"widgetType":"html"}],"isInner":false}],"isInner":false}]

