  .cb-event-banner {
    width: 100%;
    box-sizing: border-box;
    padding: 22px 28px;
    background: linear-gradient(135deg, #8f1018 0%, #b5121b 55%, #9d1119 100%);
    border: 1px solid rgba(201, 162, 39, 0.55);
    border-radius: 12px;
    position: relative;
    overflow: hidden;
    font-family: Arial, Helvetica, sans-serif;
  }

  .cb-event-banner::before {
    content: "";
    position: absolute;
    width: 180px;
    height: 180px;
    right: -70px;
    top: -100px;
    border-radius: 50%;
    background: rgba(229, 199, 102, 0.12);
  }

  .cb-event-banner::after {
    content: "";
    position: absolute;
    width: 140px;
    height: 140px;
    left: -80px;
    bottom: -100px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.06);
  }

  .cb-event-inner {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 24px;
  }

  .cb-event-content {
    min-width: 0;
  }

  .cb-event-label {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    color: #f4d978;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    margin-bottom: 7px;
  }

  .cb-event-label::before {
    content: "";
    width: 22px;
    height: 1px;
    background: #e5c766;
  }

  .cb-event-title {
    margin: 0;
    color: #ffffff;
    font-size: 22px;
    line-height: 1.25;
    font-weight: 600;
    letter-spacing: -0.2px;
  }

  .cb-event-title span {
    color: #f4d978;
  }

  .cb-event-subtitle {
    margin: 6px 0 0;
    color: rgba(255,255,255,0.78);
    font-size: 13px;
    line-height: 1.5;
  }

  .cb-book-btn {
    flex: 0 0 auto;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 12px 21px;
    background: #ffffff;
    color: #9b1119 !important;
    border: 1px solid #ffffff;
    border-radius: 6px;
    text-decoration: none !important;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.8px;
    text-transform: uppercase;
    transition: all 0.25s ease;
    box-shadow: 0 5px 18px rgba(0,0,0,0.12);
  }

  .cb-book-btn:hover {
    background: #f4d978;
    border-color: #f4d978;
    color: #7f0c13 !important;
    transform: translateY(-2px);
    box-shadow: 0 8px 22px rgba(0,0,0,0.18);
  }

  .cb-arrow {
    font-size: 15px;
    line-height: 1;
  }

  @media (max-width: 600px) {
    .cb-event-banner {
      padding: 20px;
      border-radius: 10px;
    }

    .cb-event-inner {
      align-items: flex-start;
      flex-direction: column;
      gap: 16px;
    }

    .cb-event-title {
      font-size: 20px;
    }

    .cb-book-btn {
      width: 100%;
      box-sizing: border-box;
      padding: 12px 18px;
    }
  }
</style>

