  /* ================================
     CELEBRITY BULAYE - ABOUT SECTION
     ================================ */

  .cb-about-section {
    width: 100vw !important;
    max-width: 100vw !important;
    margin-left: calc(50% - 50vw) !important;
    margin-right: calc(50% - 50vw) !important;
    box-sizing: border-box;
    padding: 90px 5vw;
    background: #fcfaf6;
    overflow: hidden;
    font-family: Arial, Helvetica, sans-serif;
  }

  .cb-about-container {
    width: 100%;
    max-width: 1280px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 0.8fr 1.5fr;
    gap: 90px;
    align-items: center;
    box-sizing: border-box;
  }

  /* ================================
     LEFT LOGO AREA
     ================================ */

  .cb-about-brand {
    position: relative;
    width: 100%;
    min-height: 430px;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .cb-about-frame {
    width: 340px;
    height: 390px;
    position: relative;
    border: 1px solid #c9a227;
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
  }

  /* Inner gold frame */
  .cb-about-frame::before {
    content: "";
    position: absolute;
    width: calc(100% - 34px);
    height: calc(100% - 34px);
    border: 1px solid #e5c766;
    box-sizing: border-box;
    pointer-events: none;
  }

  /* Small decorative gold corners */
  .cb-about-frame::after {
    content: "";
    position: absolute;
    width: 65px;
    height: 7px;
    top: -4px;
    left: 30px;
    background: #fcfaf6;
    border-left: 1px solid #c9a227;
    border-right: 1px solid #c9a227;
  }

  .cb-about-logo-wrap {
    position: relative;
    z-index: 5;
    width: 220px;
    height: 220px;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .cb-about-logo {
    width: 100%;
    max-width: 220px;
    height: auto;
    display: block;
    object-fit: contain;
    position: relative;
    z-index: 10;
    filter: drop-shadow(0 14px 22px rgba(60, 0, 0, 0.13));
  }

  /* Decorative vertical text */
  .cb-about-side-label {
    position: absolute;
    left: -43px;
    top: 50%;
    transform: translateY(-50%) rotate(-90deg);
    z-index: 8;
    background: #fcfaf6;
    padding: 6px 13px;
    color: #b5121b;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 3px;
    text-transform: uppercase;
    white-space: nowrap;
  }

  /* ================================
     RIGHT CONTENT
     ================================ */

  .cb-about-content {
    width: 100%;
    max-width: 760px;
  }

  .cb-about-eyebrow {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 18px;
    color: #b5121b;
    font-size: 11px;
    line-height: 1;
    font-weight: 700;
    letter-spacing: 3px;
    text-transform: uppercase;
  }

  .cb-about-eyebrow::before {
    content: "";
    width: 42px;
    height: 1px;
    flex: 0 0 42px;
    background: #c9a227;
  }

  .cb-about-heading {
    margin: 0 0 25px !important;
    padding: 0 !important;
    color: #171717;
    font-family: Georgia, "Times New Roman", serif;
    font-size: clamp(36px, 4vw, 54px);
    font-weight: 500;
    line-height: 1.08;
    letter-spacing: -1.5px;
  }

  .cb-about-heading span {
    color: #b5121b;
  }

  .cb-about-intro {
    margin: 0 0 21px !important;
    padding: 0 !important;
    color: #b5121b;
    font-size: 17px;
    line-height: 1.65;
    font-weight: 500;
  }

  .cb-about-text {
    margin: 0 0 19px !important;
    padding: 0 !important;
    color: #555555;
    font-size: 15px;
    line-height: 1.85;
    font-weight: 400;
  }

  .cb-about-divider {
    width: 85px;
    height: 2px;
    background: #b5121b;
    margin-top: 32px;
    position: relative;
  }

  .cb-about-divider::after {
    content: "";
    position: absolute;
    left: 0;
    top: 6px;
    width: 43px;
    height: 1px;
    background: #c9a227;
  }

  /* ================================
     TABLET
     ================================ */

  @media (max-width: 950px) {

    .cb-about-section {
      padding: 70px 35px;
    }

    .cb-about-container {
      grid-template-columns: 0.75fr 1.25fr;
      gap: 55px;
    }

    .cb-about-brand {
      min-height: 360px;
    }

    .cb-about-frame {
      width: 290px;
      height: 340px;
    }

    .cb-about-logo-wrap {
      width: 185px;
      height: 185px;
    }

    .cb-about-heading {
      font-size: 39px;
    }

    .cb-about-text {
      font-size: 14px;
    }
  }

  /* ================================
     MOBILE
     ================================ */

  @media (max-width: 700px) {

    .cb-about-section {
      padding: 60px 20px;
    }

    .cb-about-container {
      grid-template-columns: 1fr;
      gap: 48px;
    }

    .cb-about-brand {
      min-height: 320px;
    }

    .cb-about-frame {
      width: 260px;
      height: 310px;
    }

    .cb-about-logo-wrap {
      width: 165px;
      height: 165px;
    }

    .cb-about-side-label {
      left: -18px;
      font-size: 9px;
      letter-spacing: 2.5px;
    }

    .cb-about-content {
      max-width: 100%;
    }

    .cb-about-heading {
      font-size: 35px;
      letter-spacing: -0.8px;
    }

    .cb-about-intro {
      font-size: 15px;
    }

    .cb-about-text {
      font-size: 14px;
      line-height: 1.8;
    }
  }

  /* ================================
     SMALL MOBILE
     ================================ */

  @media (max-width: 420px) {

    .cb-about-section {
      padding: 50px 16px;
    }

    .cb-about-frame {
      width: 235px;
      height: 285px;
    }

    .cb-about-logo-wrap {
      width: 145px;
      height: 145px;
    }

    .cb-about-heading {
      font-size: 31px;
    }

    .cb-about-eyebrow {
      font-size: 10px;
      letter-spacing: 2px;
    }
  }
</style>


<section class="cb-about-section">

  <div class="cb-about-container">

    <!-- ================================
         LOGO / BRAND
         ================================ -->

    <div class="cb-about-brand">

      <div class="cb-about-frame">

        <div class="cb-about-side-label">
          Celebrity Bulaye
        </div>

        <div class="cb-about-logo-wrap">

          <img
            class="cb-about-logo"
            src="https://celebritybulaye.in/wp-content/uploads/2023/08/cropped-logo_celebrity_bulaye.png"
            alt="Celebrity Bulaye"
          >

        </div>

      </div>

    </div>


    <!-- ================================
         ABOUT CONTENT
         ================================ -->

    <div class="cb-about-content">

      <div class="cb-about-eyebrow">
        About Celebrity Bulaye
      </div>

      <h2 class="cb-about-heading">
        Bringing <span>Star Power</span><br>
        to Your Special Moments
      </h2>

      <p class="cb-about-intro">
        Welcome to Celebrity Bulaye, where the magic of celebrity presence awaits you.
      </p>

      <p class="cb-about-text">
        Welcome to Celebrity Bulaye, the leading online platform that connects you with the most sought-after celebrities for events and corporate brand endorsements. Our mission is to make your events truly extraordinary by bringing in the star power and charisma of renowned personalities.
      </p>

      <p class="cb-about-text">
        At Celebrity Bulaye, we understand the power of celebrity presence in making events memorable, impactful, and unforgettable. Whether you’re organizing a private party, corporate gathering, product launch, or charity event, our platform offers a seamless and efficient way to book celebrities who align with your vision and objectives.
      </p>

      <p class="cb-about-text">
        Our user-friendly website serves as a one-stop destination where you can explore an extensive catalog of celebrities from various fields, including film, music, sports, fashion, and more. Each celebrity profile provides detailed information about their expertise, experience, availability, and pricing, enabling you to make an informed decision based on your specific requirements and budget.
      </p>

      <div class="cb-about-divider"></div>

    </div>

  </div>

</section>"},"elements":[],"widgetType":"html"}],"isInner":false}],"isInner":false},{"id":"42de42d","elType":"section","settings":{"hover_parallax":[{"layer_position_vr":{"unit":"%","size":30},"layer_position_hr":{"unit":"%","size":40},"_id":"2bccf38"},{"layer_position_vr":{"unit":"%","size":60},"layer_position_hr":{"unit":"%","size":20},"_id":"77ac78d"}]},"elements":[{"id":"13d03ee","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"c2841ad","elType":"widget","settings":{"html":"<style>
  /* =========================================
