    padding: 95px 5vw;
    overflow: hidden;
    font-family: Arial, Helvetica, sans-serif;
  }

  .cb-artist-container {
    width: 100%;
    max-width: 1280px;
    margin: 0 auto;
    box-sizing: border-box;
  }

  /* =========================================
     SECTION HEADER
     ========================================= */

  .cb-artist-header {
    text-align: center;
    max-width: 780px;
    margin: 0 auto 55px;
  }

  .cb-artist-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 13px;
    color: #b5121b;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 3px;
    text-transform: uppercase;
    margin-bottom: 17px;
  }

  .cb-artist-eyebrow::before,
  .cb-artist-eyebrow::after {
    content: "";
    width: 34px;
    height: 1px;
    background: #c9a227;
  }

  .cb-artist-heading {
    margin: 0 !important;
    padding: 0 !important;
    color: #171717;
    font-family: Georgia, "Times New Roman", serif;
    font-size: clamp(38px, 4.5vw, 58px);
    font-weight: 500;
    line-height: 1.08;
    letter-spacing: -1.5px;
  }

  .cb-artist-heading span {
    color: #b5121b;
  }

  .cb-artist-description {
    margin: 20px auto 0 !important;
    padding: 0 !important;
    max-width: 680px;
    color: #666666;
    font-size: 15px;
    line-height: 1.8;
  }

  /* =========================================
     ARTIST CATEGORY GRID
     ========================================= */

  .cb-artist-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 18px;
  }

  .cb-artist-card {
    min-height: 235px;
    position: relative;
    overflow: hidden;
    background: #fcfaf6;
    border: 1px solid #e8e4dc;
    padding: 30px 25px;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    text-decoration: none !important;
    transition: all 0.3s ease;
  }

  .cb-artist-card::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    width: 4px;
    height: 0;
    background: #b5121b;
    transition: height 0.3s ease;
  }

  .cb-artist-card:hover {
    transform: translateY(-6px);
    border-color: #c9a227;
    box-shadow: 0 15px 35px rgba(0, 0, 0, 0.08);
  }

  .cb-artist-card:hover::before {
    height: 100%;
  }

  /* Large number */
  .cb-artist-number {
    position: absolute;
    right: 18px;
    top: 12px;
    color: rgba(181, 18, 27, 0.07);
    font-family: Georgia, "Times New Roman", serif;
    font-size: 80px;
    line-height: 1;
    font-weight: 700;
  }

  /* Icon */
  .cb-artist-icon {
    width: 47px;
    height: 47px;
    margin-bottom: auto;
    border: 1px solid #c9a227;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #b5121b;
    font-family: Georgia, "Times New Roman", serif;
    font-size: 20px;
    transition: all 0.3s ease;
  }

  .cb-artist-card:hover .cb-artist-icon {
    background: #b5121b;
    color: #ffffff;
    border-color: #b5121b;
  }

  .cb-artist-title {
    position: relative;
    z-index: 2;
    margin: 0 0 7px !important;
    padding: 0 !important;
    color: #222222;
    font-family: Georgia, "Times New Roman", serif;
    font-size: 22px;
    font-weight: 500;
    line-height: 1.2;
  }

  .cb-artist-text {
    position: relative;
    z-index: 2;
    margin: 0 !important;
    padding: 0 !important;
    color: #777777;
    font-size: 12px;
    line-height: 1.55;
  }

  .cb-artist-arrow {
    position: absolute;
    right: 24px;
    bottom: 27px;
    color: #b5121b;
    font-size: 20px;
    transition: transform 0.3s ease;
  }

  .cb-artist-card:hover .cb-artist-arrow {
    transform: translateX(5px);
  }

  /* =========================================
     BOTTOM CTA
     ========================================= */

  .cb-artist-bottom {
    margin-top: 48px;
    padding-top: 30px;
    border-top: 1px solid #e8e4dc;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 25px;
  }

  .cb-artist-bottom-text {
    margin: 0 !important;
    color: #555555;
    font-family: Georgia, "Times New Roman", serif;
    font-size: 20px;
  }

  .cb-artist-bottom-text span {
    color: #b5121b;
  }

  .cb-artist-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    padding: 13px 24px;
    background: #b5121b;
    color: #ffffff !important;
    border: 1px solid #b5121b;
    text-decoration: none !important;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-size: 11px;
    font-weight: 700;
    transition: all 0.25s ease;
    white-space: nowrap;
  }

  .cb-artist-button:hover {
    background: #8e0e16;
    border-color: #8e0e16;
    transform: translateY(-2px);
  }

  /* =========================================
     TABLET
     ========================================= */

  @media (max-width: 950px) {

    .cb-artist-store {
      padding: 75px 35px;
    }

    .cb-artist-grid {
      grid-template-columns: repeat(2, 1fr);
    }

    .cb-artist-bottom {
      flex-direction: column;
      align-items: flex-start;
    }
  }

  /* =========================================
     MOBILE
     ========================================= */

  @media (max-width: 600px) {

    .cb-artist-store {
      padding: 60px 18px;
    }

    .cb-artist-header {
      margin-bottom: 38px;
    }

    .cb-artist-eyebrow {
      font-size: 9px;
      letter-spacing: 2px;
    }

    .cb-artist-eyebrow::before,
    .cb-artist-eyebrow::after {
      width: 22px;
    }

    .cb-artist-heading {
      font-size: 34px;
      letter-spacing: -0.7px;
    }

    .cb-artist-description {
      font-size: 13.5px;
      line-height: 1.75;
    }

    .cb-artist-grid {
      grid-template-columns: 1fr 1fr;
      gap: 12px;
    }

    .cb-artist-card {
      min-height: 205px;
      padding: 22px 18px;
    }

    .cb-artist-icon {
      width: 40px;
      height: 40px;
      font-size: 17px;
    }

    .cb-artist-title {
      font-size: 18px;
    }

    .cb-artist-text {
      font-size: 11px;
    }

    .cb-artist-number {
      font-size: 60px;
    }

    .cb-artist-arrow {
      right: 16px;
      bottom: 20px;
    }

    .cb-artist-bottom-text {
      font-size: 17px;
    }

    .cb-artist-button {
      width: 100%;
    }
  }

  /* =========================================
     SMALL MOBILE
     ========================================= */

  @media (max-width: 390px) {

    .cb-artist-grid {
      grid-template-columns: 1fr;
    }

    .cb-artist-card {
      min-height: 190px;
    }
  }
</style>


