  /* =========================================
     CELEBRITY BULAYE - WHY CHOOSE US
     FULL WIDTH / EDGE TO EDGE
     ========================================= */

  .cb-why-section {
    width: 100vw !important;
    max-width: 100vw !important;
    margin-left: calc(50% - 50vw) !important;
    margin-right: calc(50% - 50vw) !important;
    box-sizing: border-box;
    padding: 95px 5vw;
    background: #fcfaf6;
    overflow: hidden;
    font-family: Arial, Helvetica, sans-serif;
  }

  .cb-why-container {
    width: 100%;
    max-width: 1280px;
    margin: 0 auto;
    box-sizing: border-box;
  }

  /* =========================================
     HEADER
     ========================================= */

  .cb-why-header {
    max-width: 760px;
    margin: 0 auto 58px;
    text-align: center;
  }

  .cb-why-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 13px;
    margin-bottom: 17px;
    color: #b5121b;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 3px;
    text-transform: uppercase;
  }

  .cb-why-eyebrow::before,
  .cb-why-eyebrow::after {
    content: "";
    width: 35px;
    height: 1px;
    background: #c9a227;
  }

  .cb-why-heading {
    margin: 0 !important;
    padding: 0 !important;
    color: #171717;
    font-family: Georgia, "Times New Roman", serif;
    font-size: clamp(38px, 4.5vw, 58px);
    font-weight: 500;
    line-height: 1.08;
    letter-spacing: -1.5px;
  }

  .cb-why-heading span {
    color: #b5121b;
  }

  .cb-why-subheading {
    margin: 18px auto 0 !important;
    padding: 0 !important;
    max-width: 620px;
    color: #6b6b6b;
    font-size: 15px;
    line-height: 1.8;
  }

  /* =========================================
     FEATURES
     ========================================= */

  .cb-why-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    border-top: 1px solid #ded8cc;
    border-bottom: 1px solid #ded8cc;
  }

  .cb-why-card {
    position: relative;
    min-height: 275px;
    padding: 35px 27px 30px;
    box-sizing: border-box;
    border-right: 1px solid #ded8cc;
    background: #ffffff;
    transition: all 0.3s ease;
  }

  .cb-why-card:last-child {
    border-right: none;
  }

  .cb-why-card:hover {
    background: #b5121b;
    transform: translateY(-5px);
    box-shadow: 0 18px 35px rgba(100, 0, 0, 0.14);
    z-index: 2;
  }

  /* Number */

  .cb-why-number {
    position: absolute;
    top: 18px;
    right: 22px;
    color: rgba(181, 18, 27, 0.08);
    font-family: Georgia, "Times New Roman", serif;
    font-size: 55px;
    font-weight: 700;
    line-height: 1;
    transition: color 0.3s ease;
  }

  .cb-why-card:hover .cb-why-number {
    color: rgba(255,255,255,0.12);
  }

  /* Icon */

  .cb-why-icon {
    width: 52px;
    height: 52px;
    margin-bottom: 55px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid #c9a227;
    color: #b5121b;
    font-family: Georgia, "Times New Roman", serif;
    font-size: 22px;
    transition: all 0.3s ease;
  }

  .cb-why-card:hover .cb-why-icon {
    color: #ffffff;
    border-color: #e5c766;
    background: rgba(255,255,255,0.08);
  }

  /* Title */

  .cb-why-title {
    margin: 0 0 11px !important;
    padding: 0 !important;
    color: #222222;
    font-family: Georgia, "Times New Roman", serif;
    font-size: 20px;
    font-weight: 500;
    line-height: 1.3;
    transition: color 0.3s ease;
  }

  .cb-why-card:hover .cb-why-title {
    color: #ffffff;
  }

  /* Text */

  .cb-why-text {
    margin: 0 !important;
    padding: 0 !important;
    color: #707070;
    font-size: 12.5px;
    line-height: 1.65;
    transition: color 0.3s ease;
  }

  .cb-why-card:hover .cb-why-text {
    color: rgba(255,255,255,0.78);
  }

  /* Bottom gold line */

  .cb-why-line {
    position: absolute;
    left: 27px;
    bottom: 25px;
    width: 32px;
    height: 2px;
    background: #b5121b;
    transition: width 0.3s ease, background 0.3s ease;
  }

  .cb-why-card:hover .cb-why-line {
    width: 55px;
    background: #e5c766;
  }

  /* =========================================
     BOTTOM STATEMENT
     ========================================= */

  .cb-why-bottom {
    margin-top: 52px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 20px;
    text-align: center;
  }

  .cb-why-bottom-line {
    width: 50px;
    height: 1px;
    background: #c9a227;
  }

  .cb-why-bottom-text {
    margin: 0 !important;
    padding: 0 !important;
    color: #555555;
    font-family: Georgia, "Times New Roman", serif;
    font-size: 18px;
  }

  .cb-why-bottom-text strong {
    color: #b5121b;
    font-weight: 500;
  }

  /* =========================================
     TABLET
     ========================================= */

  @media (max-width: 1050px) {

    .cb-why-section {
      padding: 75px 35px;
    }

    .cb-why-grid {
      grid-template-columns: repeat(3, 1fr);
    }

    .cb-why-card:nth-child(3) {
      border-right: none;
    }

    .cb-why-card:nth-child(4),
    .cb-why-card:nth-child(5) {
      border-top: 1px solid #ded8cc;
    }
  }

  /* =========================================
     MOBILE
     ========================================= */

  @media (max-width: 650px) {

    .cb-why-section {
      padding: 60px 18px;
    }

    .cb-why-header {
      margin-bottom: 40px;
    }

    .cb-why-eyebrow {
      font-size: 9px;
      letter-spacing: 2px;
    }

    .cb-why-eyebrow::before,
    .cb-why-eyebrow::after {
      width: 22px;
    }

    .cb-why-heading {
      font-size: 35px;
      letter-spacing: -0.8px;
    }

    .cb-why-subheading {
      font-size: 13.5px;
    }

    .cb-why-grid {
      grid-template-columns: 1fr;
    }

    .cb-why-card,
    .cb-why-card:nth-child(3),
    .cb-why-card:nth-child(4),
    .cb-why-card:nth-child(5) {
      min-height: 220px;
      border-right: none;
      border-bottom: 1px solid #ded8cc;
    }

    .cb-why-card:last-child {
      border-bottom: none;
    }

    .cb-why-icon {
      margin-bottom: 38px;
    }

    .cb-why-title {
      font-size: 21px;
    }

    .cb-why-text {
      font-size: 13px;
    }

    .cb-why-bottom {
      gap: 10px;
    }

    .cb-why-bottom-line {
      width: 25px;
    }

    .cb-why-bottom-text {
      font-size: 15px;
    }
  }
</style>


