    </div>

  </div>

</section>"},"elements":[],"widgetType":"html"}],"isInner":false}],"isInner":false},{"id":"3aa627d","elType":"section","settings":{"hover_parallax":[{"layer_position_vr":{"unit":"%","size":30},"layer_position_hr":{"unit":"%","size":40},"_id":"ec9ea9e"},{"layer_position_vr":{"unit":"%","size":60},"layer_position_hr":{"unit":"%","size":20},"_id":"0e826f2"}]},"elements":[{"id":"4e2901e","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"526b3fd","elType":"widget","settings":{"html":"<style>
/* =========================================================
   CELEBRITY BULAYE - FEATURED CELEBRITY SLIDER
   FULL WIDTH / EDGE TO EDGE
   ========================================================= */

.cb-featured-slider {
  width: 100vw !important;
  max-width: 100vw !important;
  margin-left: calc(50% - 50vw) !important;
  margin-right: calc(50% - 50vw) !important;

  position: relative;
  overflow: hidden;
  background: #f7eeee;
  font-family: Arial, Helvetica, sans-serif;
}

/* Slider wrapper */

.cb-slider-track {
  position: relative;
  width: 100%;
  min-height: 610px;
}

/* Individual slide */

.cb-slide {
  position: absolute;
  inset: 0;
  width: 100%;
  min-height: 610px;

  opacity: 0;
  visibility: hidden;
  transform: translateX(40px);

  transition:
    opacity 0.7s ease,
    transform 0.8s ease,
    visibility 0.7s ease;

  display: grid;
  grid-template-columns: 38% 62%;
}

/* Active slide */

.cb-slide.active {
  opacity: 1;
  visibility: visible;
  transform: translateX(0);
  z-index: 2;
}


/* =========================================================
   LEFT CONTENT
   ========================================================= */

.cb-slide-content {
  position: relative;
  z-index: 5;

  display: flex;
  flex-direction: column;
  justify-content: center;

  padding: 70px 45px 70px 7vw;

  box-sizing: border-box;
}

/* small top label */

.cb-slide-label {
  display: flex;
  align-items: center;
  gap: 13px;

  margin-bottom: 20px;

  color: #b5121b;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
}

.cb-slide-label::before {
  content: "";
  width: 38px;
  height: 1px;
  background: #c9a227;
}


/* Celebrity name */

.cb-slide-name {
  margin: 0 0 20px !important;
  padding: 0 !important;

  color: #171717;

  font-family: Georgia, "Times New Roman", serif;

  font-size: clamp(42px, 5vw, 70px);
  font-weight: 500;
  line-height: 1.03;

  letter-spacing: -2px;
}

.cb-slide-name span {
  color: #b5121b;
}


/* Category */

.cb-slide-category {
  margin: 0 0 22px !important;
  padding: 0 !important;

  color: #b5121b;

  font-size: 12px;
  font-weight: 700;

  letter-spacing: 2px;
  text-transform: uppercase;
}


/* Description */

.cb-slide-description {
  max-width: 500px;

  margin: 0 0 30px !important;
  padding: 0 !important;

  color: #555555;

  font-size: 15px;
  line-height: 1.8;
}


/* Button */

.cb-slide-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;

  width: fit-content;

  padding: 15px 30px;

  background: #b5121b;
  color: #ffffff !important;

  border: 1px solid #b5121b;

  text-decoration: none !important;

  font-size: 12px;
  font-weight: 700;

  letter-spacing: 1px;
  text-transform: uppercase;

  transition: all 0.3s ease;
}

.cb-slide-button:hover {
  background: #8e0e16;
  border-color: #8e0e16;

  transform: translateY(-2px);

  box-shadow: 0 10px 25px rgba(181,18,27,0.20);
}

.cb-slide-button span {
  font-size: 18px;
  line-height: 1;
}


/* =========================================================
   RIGHT IMAGE
   ========================================================= */

.cb-slide-image {
  position: relative;

  width: 100%;
  height: 610px;

  overflow: hidden;

  background: #eee2e2;
}


/* image */

.cb-slide-image img {
  width: 100%;
  height: 100%;

  display: block;

  object-fit: cover;
  object-position: center center;

  transition: transform 6s ease;
}


/* subtle zoom on active slide */

.cb-slide.active .cb-slide-image img {
  transform: scale(1.035);
}


/* gradient between content and image */

.cb-slide-image::before {
  content: "";

  position: absolute;
  z-index: 2;

  left: 0;
  top: 0;

  width: 170px;
  height: 100%;

  background: linear-gradient(
    to right,
    #f7eeee 0%,
    rgba(247,238,238,0.75) 20%,
    rgba(247,238,238,0) 100%
  );

  pointer-events: none;
}


/* bottom subtle gradient */

.cb-slide-image::after {
  content: "";

  position: absolute;
  z-index: 2;

  left: 0;
  right: 0;
  bottom: 0;

  height: 100px;

  background: linear-gradient(
    to top,
    rgba(0,0,0,0.16),
    transparent
  );

  pointer-events: none;
}


/* =========================================================
   ARROWS
   ========================================================= */

.cb-slider-arrow {
  position: absolute;

  top: 50%;
  transform: translateY(-50%);

  z-index: 20;

  width: 46px;
  height: 46px;

  display: flex;
  align-items: center;
  justify-content: center;

  border: none;

  background: rgba(23,23,23,0.80);

  color: #ffffff;

  font-size: 25px;

  cursor: pointer;

  transition: all 0.25s ease;
}

.cb-slider-arrow:hover {
  background: #b5121b;
}

.cb-slider-prev {
  left: 18px;
}

.cb-slider-next {
  right: 18px;
}


/* =========================================================
   SLIDER BOTTOM NAVIGATION
   ========================================================= */

.cb-slider-bottom {
  position: absolute;

  z-index: 30;

  left: 7vw;
  bottom: 30px;

  display: flex;
  align-items: center;
  gap: 9px;
}

.cb-slider-dot {
  width: 32px;
  height: 2px;

  padding: 0;
  border: none;

  background: rgba(181,18,27,0.28);

  cursor: pointer;

  transition: all 0.3s ease;
}

.cb-slider-dot.active {
  width: 55px;
  background: #b5121b;
}


/* slide counter */

