<script>
(function () {

  const slides = document.querySelectorAll(".cb-slide");
  const dots = document.querySelectorAll(".cb-slider-dot");

  const nextButton = document.querySelector(".cb-slider-next");
  const prevButton = document.querySelector(".cb-slider-prev");

  const counter = document.getElementById("cbCurrentSlide");

  let current = 0;

  let autoSlide;


  /* ---------------------------------------------
     SHOW SLIDE
     --------------------------------------------- */

  function showSlide(index) {

    slides.forEach(function (slide) {
      slide.classList.remove("active");
    });

    dots.forEach(function (dot) {
      dot.classList.remove("active");
    });


    slides[index].classList.add("active");

    if (dots[index]) {
      dots[index].classList.add("active");
    }


    counter.textContent =
      String(index + 1).padStart(2, "0");

    current = index;
  }


  /* ---------------------------------------------
     NEXT
     --------------------------------------------- */

  function nextSlide() {

    let next = current + 1;

    if (next >= slides.length) {
      next = 0;
    }

    showSlide(next);
  }


  /* ---------------------------------------------
     PREVIOUS
     --------------------------------------------- */

  function previousSlide() {

    let previous = current - 1;

    if (previous < 0) {
      previous = slides.length - 1;
    }

    showSlide(previous);
  }


  /* ---------------------------------------------
     AUTO SLIDE
     --------------------------------------------- */

  function startAutoSlide() {

    clearInterval(autoSlide);

    autoSlide = setInterval(function () {
      nextSlide();
    }, 5000);

  }


  /* ---------------------------------------------
     ARROW EVENTS
     --------------------------------------------- */

  nextButton.addEventListener("click", function () {

    nextSlide();
    startAutoSlide();

  });


  prevButton.addEventListener("click", function () {

    previousSlide();
    startAutoSlide();

  });


  /* ---------------------------------------------
     DOT EVENTS
     --------------------------------------------- */

  dots.forEach(function (dot, index) {

    dot.addEventListener("click", function () {

      showSlide(index);
      startAutoSlide();

    });

  });


  /* ---------------------------------------------
     START
     --------------------------------------------- */

  showSlide(0);
  startAutoSlide();


})();
</script>"},"elements":[],"widgetType":"html"}],"isInner":false}],"isInner":false},{"id":"0c36cf1","elType":"section","settings":{"hover_parallax":[{"layer_position_vr":{"unit":"%","size":30},"layer_position_hr":{"unit":"%","size":40},"_id":"8670557"},{"layer_position_vr":{"unit":"%","size":60},"layer_position_hr":{"unit":"%","size":20},"_id":"e9d14f1"}]},"elements":[{"id":"9e26312","elType":"column","settings":{"_column_size":100,"_inline_size":null},"elements":[{"id":"d59501e","elType":"widget","settings":{"html":"<style>
