/* ================================
   CELEBRITY BULAYE - CONTACT FORM
================================ */

.cb-contact-section {
    width: 100vw !important;
    max-width: 100vw !important;
    margin-left: calc(50% - 50vw) !important;
    margin-right: calc(50% - 50vw) !important;
    padding: 90px 6%;
    background: #FCFAF6;
    box-sizing: border-box;
    overflow: hidden;
}

.cb-contact-wrap {
    max-width: 1250px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: 0.9fr 1.1fr;
    gap: 70px;
    align-items: center;
}

/* LEFT IMAGE */

.cb-contact-image {
    position: relative;
    height: 620px;
    overflow: hidden;
}

.cb-contact-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    transition: transform 0.7s ease;
}

.cb-contact-image:hover img {
    transform: scale(1.03);
}

.cb-contact-image::after {
    content: "";
    position: absolute;
    inset: 18px;
    border: 1px solid rgba(201,162,39,0.7);
    pointer-events: none;
}

/* IMAGE LABEL */

.cb-contact-image-label {
    position: absolute;
    bottom: 35px;
    left: 35px;
    z-index: 2;
    background: rgba(255,255,255,0.95);
    padding: 18px 24px;
    border-left: 4px solid #B5121B;
}

.cb-contact-image-label small {
    display: block;
    font-family: Arial, sans-serif;
    font-size: 10px;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: #B5121B;
    font-weight: 700;
    margin-bottom: 5px;
}

.cb-contact-image-label strong {
    font-family: Georgia, serif;
    font-size: 20px;
    color: #171717;
    font-weight: 500;
}

/* RIGHT CONTENT */

.cb-contact-content {
    padding-right: 15px;
}

.cb-contact-eyebrow {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 18px;
    font-family: Arial, sans-serif;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: #B5121B;
}

.cb-contact-eyebrow::before {
    content: "";
    width: 38px;
    height: 1px;
    background: #C9A227;
}

.cb-contact-content h2 {
    margin: 0;
    font-family: Georgia, "Times New Roman", serif;
    font-size: clamp(38px, 4vw, 58px);
    line-height: 1.12;
    font-weight: 500;
    color: #171717;
}

.cb-contact-content h2 span {
    color: #B5121B;
}

.cb-contact-intro {
    margin: 18px 0 34px;
    max-width: 570px;
    font-family: Arial, sans-serif;
    font-size: 16px;
    line-height: 1.7;
    color: #6B6B6B;
}

/* FORM */

.cb-contact-form {
    width: 100%;
}

.cb-form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
}

.cb-form-group {
    margin-bottom: 20px;
}

.cb-form-group label {
    display: block;
    margin-bottom: 8px;
    font-family: Arial, sans-serif;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.7px;
    color: #333;
}

.cb-form-group input,
.cb-form-group textarea {
    width: 100%;
    box-sizing: border-box;
    border: 1px solid #DED9CF;
    background: #FFFFFF;
    color: #171717;
    padding: 15px 16px;
    font-family: Arial, sans-serif;
    font-size: 14px;
    outline: none;
    border-radius: 2px;
    transition: border-color 0.25s ease, box-shadow 0.25s ease;
}

.cb-form-group input {
    height: 52px;
}

.cb-form-group textarea {
    min-height: 125px;
    resize: vertical;
}

.cb-form-group input:focus,
.cb-form-group textarea:focus {
    border-color: #B5121B;
    box-shadow: 0 0 0 2px rgba(181,18,27,0.07);
}

.cb-form-group input::placeholder,
.cb-form-group textarea::placeholder {
    color: #A3A3A3;
}

/* BUTTON */

.cb-submit-btn {
    position: relative;
    width: 100%;
    height: 55px;
    border: none;
    background: #B5121B;
    color: #FFFFFF;
    cursor: pointer;
    font-family: Arial, sans-serif;
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    transition: all 0.3s ease;
}

.cb-submit-btn:hover {
    background: #8E0E16;
    transform: translateY(-1px);
}

.cb-submit-btn:disabled {
    opacity: 0.7;
    cursor: wait;
    transform: none;
}

/* LOADING */

.cb-form-status {
    margin-top: 18px;
    font-family: Arial, sans-serif;
    font-size: 14px;
    text-align: center;
    display: none;
}

.cb-form-status.error {
    display: block;
    color: #B5121B;
}

/* THANK YOU */

.cb-thank-you {
    display: none;
    text-align: center;
    padding: 45px 25px;
    border: 1px solid #E8E4DC;
    background: #FFFFFF;
}

.cb-thank-you.show {
    display: block;
    animation: cbThankYou 0.5s ease;
}

.cb-thank-icon {
    width: 58px;
    height: 58px;
    margin: 0 auto 20px;
    border: 1px solid #C9A227;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #B5121B;
    font-size: 25px;
}

.cb-thank-you h3 {
    margin: 0 0 10px;
    font-family: Georgia, serif;
    font-size: 30px;
    font-weight: 500;
    color: #171717;
}

.cb-thank-you p {
    margin: 0;
    font-family: Arial, sans-serif;
    font-size: 14px;
    line-height: 1.6;
    color: #6B6B6B;
}

@keyframes cbThankYou {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* MOBILE */

