<section class="cb-contact-section">

    <div class="cb-contact-wrap">

        <!-- LEFT: CELEBRITY IMAGE -->
        <div class="cb-contact-image">

            <img
                src="https://images.unsplash.com/photo-1501386761578-eac5c94b800a?auto=format&fit=crop&w=1000&q=85"
                alt="Celebrity Event"
            >

            <div class="cb-contact-image-label">
                <small>Celebrity Bulaye</small>
                <strong>Make It Extraordinary</strong>
            </div>

        </div>


        <!-- RIGHT: CONTACT FORM -->
        <div class="cb-contact-content">

            <div class="cb-contact-eyebrow">
                Get In Touch
            </div>

            <h2>
                Let's Make Your Event
                <span>Unforgettable</span>
            </h2>

            <p class="cb-contact-intro">
                Looking to book a celebrity for your event, brand campaign,
                corporate gathering or special occasion? Tell us what you have
                in mind and our team will get back to you.
            </p>


            <!-- FORM -->
            <form
                class="cb-contact-form"
                id="cbContactForm"
                action="https://formspree.io/f/mljeyaoe"
                method="POST"
            >

                <div class="cb-form-row">

                    <div class="cb-form-group">
                        <label for="cb-name">Name</label>
                        <input
                            type="text"
                            id="cb-name"
                            name="name"
                            placeholder="Your Name"
                            required
                        >
                    </div>

                    <div class="cb-form-group">
                        <label for="cb-email">Email</label>
                        <input
                            type="email"
                            id="cb-email"
                            name="email"
                            placeholder="Your Email"
                            required
                        >
                    </div>

                </div>


                <div class="cb-form-group">
                    <label for="cb-mobile">Mobile</label>
                    <input
                        type="tel"
                        id="cb-mobile"
                        name="mobile"
                        placeholder="Your Mobile Number"
                        pattern="[0-9+\-\s()]{10,}"
                        required
                    >
                </div>


                <div class="cb-form-group">
                    <label for="cb-message">Message</label>
                    <textarea
                        id="cb-message"
                        name="message"
                        placeholder="Tell us about your event or celebrity requirement..."
                        required
                    ></textarea>
                </div>


                <button
                    type="submit"
                    class="cb-submit-btn"
                    id="cbSubmitBtn"
                >
                    Submit Inquiry
                </button>

                <div
                    class="cb-form-status"
                    id="cbFormStatus"
                ></div>

            </form>


            <!-- THANK YOU MESSAGE -->
            <div
                class="cb-thank-you"
                id="cbThankYou"
            >

                <div class="cb-thank-icon">
                    ✓
                </div>

                <h3>Thank You!</h3>

                <p>
                    Your inquiry has been received successfully.
                    Our team will get in touch with you shortly.
                </p>

            </div>

        </div>

    </div>

</section>


<script>
(function () {

    const form = document.getElementById("cbContactForm");
    const button = document.getElementById("cbSubmitBtn");
    const status = document.getElementById("cbFormStatus");
    const thankYou = document.getElementById("cbThankYou");

    if (!form) return;

    form.addEventListener("submit", async function (event) {

        event.preventDefault();

        button.disabled = true;
        button.textContent = "Sending...";
        status.style.display = "none";
        status.classList.remove("error");

        const formData = new FormData(form);

        try {

            const response = await fetch(form.action, {
                method: "POST",
                body: formData,
                headers: {
                    "Accept": "application/json"
                }
            });

            if (response.ok) {

                form.style.display = "none";
                thankYou.classList.add("show");

            } else {

                throw new Error("Form submission failed");

            }

        } catch (error) {

            status.textContent =
                "Something went wrong. Please try again.";

            status.classList.add("error");
            status.style.display = "block";

            button.disabled = false;
            button.textContent = "Submit Inquiry";
        }

    });

})();
